from collections import defaultdict


class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected."""
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        # Collect all unique tasks from both keys and dependency lists
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        if not all_tasks:
            return []

        # Map each task to the set of tasks it directly depends on
        dep_graph: dict[str, set[str]] = {task: set() for task in all_tasks}
        for task, deps in dependencies.items():
            dep_graph[task].update(deps)

        # In-degree represents the count of unresolved dependencies for each task
        in_degree: dict[str, int] = {}
        # Adjacency list mapping a task to the tasks that depend on it
        dependents: dict[str, list[str]] = defaultdict(list)

        for task, deps in dep_graph.items():
            in_degree[task] = len(deps)
            for dep in deps:
                dependents[dep].append(task)

        # Tasks with no dependencies start in stage 0
        current_stage = [task for task, degree in in_degree.items() if degree == 0]
        stages: list[list[str]] = []
        resolved_count = 0

        while current_stage:
            current_stage.sort()
            stages.append(current_stage)
            resolved_count += len(current_stage)

            next_stage: list[str] = []
            for task in current_stage:
                for dependent in dependents[task]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_stage.append(dependent)
            current_stage = next_stage

        if resolved_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected among tasks.")

        return stages
