from collections import deque
import threading
import time
from typing import Optional


class SlidingWindowRateLimiter:
    """A thread-safe in-memory sliding window rate limiter."""

    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests < 0:
            raise ValueError("max_requests must be non-negative")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")

        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self._lock = threading.Lock()
        self._history: dict[str, deque[float]] = {}

    def _cleanup(self, key: str, current_time: float) -> Optional[deque[float]]:
        queue = self._history.get(key)
        if queue is None:
            return None

        cutoff = current_time - self.window_seconds
        while queue and queue[0] <= cutoff:
            queue.popleft()

        if not queue:
            del self._history[key]
            return None

        return queue

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        with self._lock:
            current_time = time.time() if timestamp is None else float(timestamp)

            if self.max_requests <= 0:
                return False, float(self.window_seconds)

            queue = self._cleanup(key, current_time)
            if queue is None:
                queue = deque()
                self._history[key] = queue

            if len(queue) < self.max_requests:
                if queue and current_time < queue[-1]:
                    for i, t in enumerate(queue):
                        if t > current_time:
                            queue.insert(i, current_time)
                            break
                else:
                    queue.append(current_time)
                return True, 0.0
            else:
                oldest = queue[0]
                retry_after = max(0.0, (oldest + self.window_seconds) - current_time)
                return False, retry_after

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        with self._lock:
            current_time = time.time() if timestamp is None else float(timestamp)

            if self.max_requests <= 0:
                return 0

            queue = self._cleanup(key, current_time)
            used = len(queue) if queue is not None else 0
            return max(0, self.max_requests - used)
