import asyncio
import inspect
from typing import Any, Callable, Optional, Set


class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be >= 0")

        self._concurrency = concurrency
        self._max_queue_size = max_queue_size

        try:
            self._queue: Optional[asyncio.PriorityQueue] = asyncio.PriorityQueue(maxsize=max_queue_size)
            self._shutdown_event: Optional[asyncio.Event] = asyncio.Event()
        except RuntimeError:
            # If instantiated outside an active event loop
            self._queue = None
            self._shutdown_event = None

        self._counter: int = 0
        self._started: bool = False
        self._shutting_down: bool = False
        self._workers: list[asyncio.Task] = []
        self._pending_puts: Set[asyncio.Task] = set()

    def _ensure_resources(self) -> None:
        if self._queue is None:
            self._queue = asyncio.PriorityQueue(maxsize=self._max_queue_size)
        if self._shutdown_event is None:
            self._shutdown_event = asyncio.Event()

    async def start(self) -> None:
        """Spawns worker tasks."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")
        if self._started:
            return

        self._ensure_resources()
        self._started = True
        self._workers = [
            asyncio.create_task(self._worker_loop(i), name=f"AsyncWorkerPool-worker-{i}")
            for i in range(self._concurrency)
        ]

    async def submit(
        self, coro_func: Callable[..., Any], *args: Any, priority: int = 0, **kwargs: Any
    ) -> asyncio.Future:
        """
        Enqueues a coroutine function coro_func(*args, **kwargs) to be executed by pool workers.
        Higher priority integer executes before lower priority integers.
        Returns an asyncio.Future resolving with the result or exception.
        """
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        self._ensure_resources()
        assert self._queue is not None
        assert self._shutdown_event is not None

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()

        self._counter += 1
        # Negate priority so PriorityQueue (min-heap) yields higher priority values first.
        # self._counter acts as a FIFO tie-breaker and prevents comparing unorderable callables.
        item = (-priority, self._counter, future, coro_func, args, kwargs)

        if not self._queue.full():
            self._queue.put_nowait(item)
            if self._shutting_down:
                if not future.done():
                    future.cancel()
                raise RuntimeError("Pool is shutting down")
            return future

        # Queue is full; wait for space or pool shutdown to prevent deadlocks
        put_task = loop.create_task(self._queue.put(item))
        self._pending_puts.add(put_task)
        shutdown_task = loop.create_task(self._shutdown_event.wait())

        try:
            done, _ = await asyncio.wait(
                {put_task, shutdown_task},
                return_when=asyncio.FIRST_COMPLETED
            )
        except asyncio.CancelledError:
            put_task.cancel()
            shutdown_task.cancel()
            if not future.done():
                future.cancel()
            raise
        finally:
            self._pending_puts.discard(put_task)

        if shutdown_task in done or self._shutting_down:
            put_task.cancel()
            shutdown_task.cancel()
            if not future.done():
                future.cancel()
            raise RuntimeError("Pool is shutting down")

        shutdown_task.cancel()
        return future

    async def _worker_loop(self, worker_id: int) -> None:
        assert self._queue is not None
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            _, _, future, coro_func, args, kwargs = item

            # If future was cancelled before execution started, discard cleanly
            if future.cancelled():
                self._queue.task_done()
                continue

            async def _execute() -> Any:
                res = coro_func(*args, **kwargs)
                if inspect.isawaitable(res) or asyncio.iscoroutine(res):
                    return await res
                return res

            task = asyncio.create_task(_execute())

            def _on_fut_done(f: asyncio.Future) -> None:
                if f.cancelled() and not task.done():
                    task.cancel()

            future.add_done_callback(_on_fut_done)

            try:
                result = await task
                if not future.done():
                    future.set_result(result)
            except asyncio.CancelledError as exc:
                if not future.done():
                    future.cancel()

                # Determine if cancellation was targeted at the worker itself or the task
                current_task = asyncio.current_task()
                is_worker_cancelling = False
                if current_task is not None:
                    if hasattr(current_task, "cancelling") and current_task.cancelling() > 0:
                        is_worker_cancelling = True
                    elif current_task.cancelled():
                        is_worker_cancelling = True

                if not task.done() or is_worker_cancelling:
                    if not task.done():
                        task.cancel()
                        try:
                            await task
                        except (asyncio.CancelledError, Exception):
                            pass
                    raise exc
            except Exception as exc:
                if not future.done():
                    future.set_exception(exc)
            finally:
                future.remove_done_callback(_on_fut_done)
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """
        Shuts down the pool.
        - If drain=True, waits for queued tasks to complete before stopping workers.
        - If drain=False, cancels all queued and executing tasks immediately.
        - Respects optional timeout seconds.
        """
        if self._shutting_down and not self._workers and (self._queue is None or self._queue.empty()):
            return

        self._ensure_resources()
        assert self._queue is not None
        assert self._shutdown_event is not None

        self._shutting_down = True
        self._shutdown_event.set()

        # Unblock any pending submit calls waiting for queue space
        for put_task in list(self._pending_puts):
            put_task.cancel()

        async def _do_shutdown() -> None:
            assert self._queue is not None
            if drain:
                # If workers were not explicitly started, start them to drain the backlog
                if not self._started and not self._queue.empty():
                    self._started = True
                    self._workers = [
                        asyncio.create_task(self._worker_loop(i), name=f"AsyncWorkerPool-worker-{i}")
                        for i in range(self._concurrency)
                    ]

                if self._workers:
                    await self._queue.join()
                    for worker in self._workers:
                        worker.cancel()
                    await asyncio.gather(*self._workers, return_exceptions=True)
            else:
                # Cancel all unstarted queued tasks
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        _, _, future, _, _, _ = item
                        if not future.done():
                            future.cancel()
                        self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break

                # Cancel all active worker tasks immediately
                for worker in self._workers:
                    worker.cancel()
                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)

        try:
            if timeout is not None and timeout > 0:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            else:
                await _do_shutdown()
        except (asyncio.TimeoutError, TimeoutError):
            # Enforce immediate cancellation of remaining tasks and workers on timeout
            assert self._queue is not None
            while not self._queue.empty():
                try:
                    item = self._queue.get_nowait()
                    _, _, future, _, _, _ = item
                    if not future.done():
                        future.cancel()
                    self._queue.task_done()
                except asyncio.QueueEmpty:
                    break

            for worker in self._workers:
                worker.cancel()
            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)
            raise
        finally:
            self._started = False
            self._workers = []
