from typing import Any, Optional


class QuorumCluster:
    def __init__(self, node_ids: list[str]) -> None:
        """
        Initializes cluster state with given unique node IDs.
        Total node count N = len(node_ids). Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids: list[str] = list(node_ids)
        self.quorum_threshold: int = len(self.node_ids) // 2 + 1

        # Per-node local key-value store and version mapping
        self.store: dict[str, dict[str, Any]] = {node: {} for node in self.node_ids}
        self.node_versions: dict[str, dict[str, int]] = {node: {} for node in self.node_ids}

        # Monotonically increasing counter to order committed writes
        self._version_counter: int = 0

        # Current active network partitions represented as sets of reachable nodes
        self.partitions: list[set[str]] = [set(self.node_ids)]

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in group_a
        can only talk to group_a, and group_b only to group_b.
        Any nodes not explicitly in group_a or group_b are isolated as singletons.
        """
        set_a = set(group_a)
        set_b = set(group_b)

        self.partitions = [set_a, set_b]

        # Isolate any nodes not included in either partition
        assigned = set_a | set_b
        for node in self.node_ids:
            if node not in assigned:
                self.partitions.append({node})

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        # Restore full connectivity
        self.partitions = [set(self.node_ids)]

        # Determine the latest committed state for each key across all nodes
        latest_state: dict[str, Any] = {}
        latest_versions: dict[str, int] = {}

        for node in self.node_ids:
            for key, ver in self.node_versions[node].items():
                if key not in latest_versions or ver > latest_versions[key]:
                    latest_versions[key] = ver
                    latest_state[key] = self.store[node][key]

        # Replicate the latest state to all nodes
        for node in self.node_ids:
            self.store[node] = dict(latest_state)
            self.node_versions[node] = dict(latest_versions)

    def _get_partition(self, node: str) -> set[str]:
        """Returns the network partition containing the given node."""
        for p in self.partitions:
            if node in p:
                return p
        return set()

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write from from_node.
        If from_node belongs to a partition having a STRICT MAJORITY
        (active partition size >= quorum threshold), the write commits,
        updates state in all nodes within that partition, and returns True.
        Otherwise, returns False.
        """
        if from_node not in self.store:
            return False

        partition = self._get_partition(from_node)

        # Check if the active partition meets or exceeds the quorum threshold
        if len(partition) >= self.quorum_threshold:
            self._version_counter += 1
            for node in partition:
                if node in self.store:
                    self.store[node][key] = value
                    self.node_versions[node][key] = self._version_counter
            return True

        return False

    def read_value(self, from_node: str, key: str) -> Any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node not in self.store:
            return None
        return self.store[from_node].get(key, None)
