import re


def is_safe_sql_query(query: str) -> tuple[bool, str]:
    """
    Inspects a SQL query or input fragment for malicious SQL injection signatures.

    Requirements met:
    1. Detects malicious SQL injection signatures:
       - Boolean/Tautology injection (e.g., "' OR '1'='1'", '" OR 1=1 --', "admin'--")
       - Stacked query execution (e.g., '; DROP TABLE', '; EXEC xp_cmdshell', '; DELETE FROM')
       - UNION-based data exfiltration (e.g., 'UNION SELECT', 'UNION ALL SELECT')
       - Time-based blind execution (e.g., 'pg_sleep(', 'WAITFOR DELAY', 'BENCHMARK(')
       - Obfuscation / inline comment evasion (e.g., '/*!50000SELECT*/', 'UN/**/ION')
    2. Allows legitimate queries, including:
       - JSON extraction operators (e.g., "SELECT data->>'user_id' FROM events")
       - Window functions (e.g., "SELECT id, AVG(amount) OVER (PARTITION BY category) FROM sales")
       - Text containing words like 'union', 'delay', or 'sleep' inside quoted string values
         (e.g., "WHERE status = 'delayed'" or "WHERE description = 'unionized employees'")
    3. Case-insensitive inspection with normalized whitespace handling.

    Returns:
        tuple[bool, str]: (False, "<REASON>") if an injection signature is detected,
                          or (True, "SAFE") if legitimate.
    """
    if not isinstance(query, str):
        return False, "Query must be a string"

    raw = query.strip()
    if not raw:
        return False, "Query cannot be empty"

    # Tokenize the query into CODE, STR, COMMENT, and UNCLOSED_STR tokens.
    # This prevents inspecting keywords that exist legitimately inside string literals.
    chunks: list[tuple[str, str, str]] = []
    i = 0
    n = len(raw)
    code_start = 0

    while i < n:
        # Check for block comment /* ... */
        if raw[i:i + 2] == "/*":
            if i > code_start:
                chunks.append(("CODE", raw[code_start:i], ""))
            comment_start = i
            i += 2
            while i < n and raw[i:i + 2] != "*/":
                i += 1
            if i < n:
                i += 2
            chunks.append(("COMMENT", raw[comment_start:i], "/*"))
            code_start = i
            continue

        # Check for line comment: -- or #
        elif raw[i:i + 2] == "--" or raw[i] == "#":
            if i > code_start:
                chunks.append(("CODE", raw[code_start:i], ""))
            comment_start = i
            comment_type = "--" if raw[i:i + 2] == "--" else "#"
            i += 2 if comment_type == "--" else 1
            while i < n and raw[i] not in ("\r", "\n"):
                i += 1
            chunks.append(("COMMENT", raw[comment_start:i], comment_type))
            code_start = i
            continue

        # Check for single-quoted string literal '...'
        elif raw[i] == "'":
            if i > code_start:
                chunks.append(("CODE", raw[code_start:i], ""))
            str_start = i
            i += 1
            closed = False
            while i < n:
                if raw[i] == "'":
                    if i + 1 < n and raw[i + 1] == "'":
                        i += 2  # SQL escaped single quote: ''
                        continue
                    i += 1
                    closed = True
                    break
                elif raw[i] == "\\":
                    i += 2  # Backslash escape
                    continue
                else:
                    i += 1
            if closed:
                chunks.append(("STR", raw[str_start:i], "'"))
                code_start = i
            else:
                chunks.append(("UNCLOSED_STR", raw[str_start:], "'"))
                code_start = n
                break

        # Check for double-quoted string literal "..."
        elif raw[i] == '"':
            if i > code_start:
                chunks.append(("CODE", raw[code_start:i], ""))
            str_start = i
            i += 1
            closed = False
            while i < n:
                if raw[i] == '"':
                    if i + 1 < n and raw[i + 1] == '"':
                        i += 2  # Escaped double quote: ""
                        continue
                    i += 1
                    closed = True
                    break
                elif raw[i] == "\\":
                    i += 2  # Backslash escape
                    continue
                else:
                    i += 1
            if closed:
                chunks.append(("STR", raw[str_start:i], '"'))
                code_start = i
            else:
                chunks.append(("UNCLOSED_STR", raw[str_start:], '"'))
                code_start = n
                break
        else:
            i += 1

    if code_start < n:
        chunks.append(("CODE", raw[code_start:], ""))

    # 1. Check for Obfuscation / inline comment evasion
    # MySQL conditional execution comments (e.g., /*!50000SELECT*/ or /*!SELECT*/) outside strings
    for chunk in chunks:
        if chunk[0] == "COMMENT" and chunk[2] == "/*":
            content = chunk[1]
            if re.match(r"^/\*!\d*", content):
                return False, "Obfuscation / inline comment evasion detected: MySQL conditional execution comment"

    # Inline comments breaking words/tokens (e.g., UN/**/ION, SEL/**/ECT)
    for idx, chunk in enumerate(chunks):
        if chunk[0] == "COMMENT" and chunk[2] == "/*":
            content = chunk[1]
            # Legitimate optimizer hints like /*+ INDEX(...) */ are allowed
            if content.startswith("/*+"):
                continue
            preceded_by_word = False
            followed_by_word = False
            if idx > 0 and chunks[idx - 1][0] == "CODE":
                prev_code = chunks[idx - 1][1]
                if prev_code and re.search(r"\w$", prev_code):
                    preceded_by_word = True
            if idx + 1 < len(chunks) and chunks[idx + 1][0] == "CODE":
                next_code = chunks[idx + 1][1]
                if next_code and re.match(r"^\w", next_code):
                    followed_by_word = True

            if preceded_by_word and followed_by_word:
                return False, "Obfuscation / inline comment evasion detected: inline comment breaking token"

    # Multiple consecutive comments outside strings (e.g., /**//**/)
    for idx, chunk in enumerate(chunks):
        if chunk[0] == "COMMENT" and chunk[2] == "/*":
            if idx + 1 < len(chunks) and chunks[idx + 1][0] == "COMMENT" and chunks[idx + 1][2] == "/*":
                return False, "Obfuscation / inline comment evasion detected: consecutive comments"

    # Null byte injection / URL-encoded null byte evasion
    if "\x00" in raw or "%00" in raw.lower():
        return False, "Obfuscation / inline comment evasion detected: null byte evasion"

    # 2. Check for quote-breakout boolean injection signatures
    # Payloads starting with a quote followed by boolean operators (e.g., ' OR '1'='1', " OR 1=1 --, ' OR ''=')
    if re.match(r'''^(?:'|")\s*(?:\)?\s*)?(?:OR|AND)\b''', raw, re.IGNORECASE):
        return False, "Boolean/Tautology injection detected: quote breakout with boolean operator"

    # Payloads starting with a quote followed by comment delimiters (e.g., '--, "--, '#, '/*)
    if re.match(r'''^(?:'|")\s*(?:--|#|/\*)''', raw):
        return False, "Boolean/Tautology injection detected: quote breakout with comment"

    # Unclosed string literals resulting from quote-breakout injection payloads (e.g., admin'--, " OR 1=1 --)
    for chunk in chunks:
        if chunk[0] == "UNCLOSED_STR":
            return False, "Boolean/Tautology injection detected: unclosed string literal / quote breakout"

    # Comment terminating query immediately after a string literal on the same line (e.g. admin'--, 'admin'--)
    for idx, chunk in enumerate(chunks):
        if chunk[0] == "STR":
            if idx + 1 < len(chunks) and chunks[idx + 1][0] == "COMMENT":
                return False, "Boolean/Tautology injection detected: inline comment terminating query"
            if idx + 2 < len(chunks) and chunks[idx + 1][0] == "CODE" and not re.search(r"[\r\n]", chunks[idx + 1][1]):
                next_chunk = chunks[idx + 2]
                if next_chunk[0] == "COMMENT" and re.match(r"^(?:--|#)\s*['\"]", next_chunk[1]):
                    return False, "Boolean/Tautology injection detected: comment cutting off string delimiter"

    # Reconstruct normalized SQL code for structural inspection:
    # - Replace quoted strings with placeholder 'STR' so legitimate string contents are ignored
    # - Replace comments with a single space to avoid artificial token merging
    code_parts: list[str] = []
    for chunk in chunks:
        if chunk[0] == "CODE":
            code_parts.append(chunk[1])
        elif chunk[0] == "STR":
            code_parts.append(" 'STR' ")
        elif chunk[0] == "COMMENT":
            code_parts.append(" ")

    code_only = "".join(code_parts)
    normalized_code = " ".join(code_only.split())

    # 3. Check for Stacked Query execution
    # Semicolon followed by executable SQL commands (e.g., ; DROP TABLE, ; EXEC xp_cmdshell, ; DELETE FROM)
    stacked_pattern = (
        r";\s*(?:DROP|DELETE|UPDATE|INSERT|EXEC|EXECUTE|XP_CMDSHELL|"
        r"TRUNCATE|ALTER|CREATE|DECLARE|MERGE|GRANT|REVOKE|SHUTDOWN|"
        r"SELECT|CALL|DO|SHOW|USE)\b"
    )
    if re.search(stacked_pattern, normalized_code, re.IGNORECASE):
        return False, "Stacked query execution detected"

    # Query starting with a semicolon followed by a command
    if re.match(r"^\s*;\s*\w+", raw):
        return False, "Stacked query execution detected"

    # 4. Check for UNION-based data exfiltration
    # e.g., UNION SELECT, UNION ALL SELECT, UNION DISTINCT SELECT, UNION (SELECT ...)
    union_pattern = r"\bUNION(?:\s+(?:ALL|DISTINCT))?\s*\(?\s*SELECT\b"
    if re.search(union_pattern, normalized_code, re.IGNORECASE):
        return False, "UNION-based data exfiltration detected"

    # 5. Check for Time-based blind execution
    # e.g., pg_sleep(, WAITFOR DELAY, BENCHMARK(, sleep(, dbms_pipe.receive_message(
    time_based_patterns = [
        (r"\bpg_sleep\s*\(", "Time-based blind execution detected: pg_sleep"),
        (r"\bWAITFOR\s+DELAY\b", "Time-based blind execution detected: WAITFOR DELAY"),
        (r"\bBENCHMARK\s*\(", "Time-based blind execution detected: BENCHMARK"),
        (r"\bsleep\s*\(", "Time-based blind execution detected: sleep"),
        (r"\bdbms_pipe\.receive_message\s*\(", "Time-based blind execution detected: dbms_pipe"),
        (r"\bdbms_lock\.sleep\s*\(", "Time-based blind execution detected: dbms_lock"),
    ]
    for pattern, msg in time_based_patterns:
        if re.search(pattern, normalized_code, re.IGNORECASE):
            return False, msg

    # 6. Check for Boolean / Tautology injection in query code
    # Numeric or boolean tautologies (e.g., OR 1=1, AND 1=1, OR true)
    tautology_code_patterns = [
        r"\b(?:OR|AND)\s*\(?\s*(\d+)\s*=\s*\1\s*\)?",
        r"\b(?:OR|AND)\s*\(?\s*(\d+)\s*(?:<>|!=)\s*(?!\1)\d+\s*\)?",
        r"\b(?:OR|AND)\s+true\b",
        r"\b(?:OR|AND)\s*\(?\s*true\s*=\s*true\s*\)?",
    ]
    for pattern in tautology_code_patterns:
        if re.search(pattern, normalized_code, re.IGNORECASE):
            return False, "Boolean/Tautology injection detected: tautological condition"

    # String comparison tautologies (e.g., OR '1'='1', OR 'a'='a', OR "a"="a")
    for idx, chunk in enumerate(chunks):
        if chunk[0] == "CODE" and re.search(r"\b(?:OR|AND)\s*\(?\s*$", chunk[1], re.IGNORECASE):
            # Inspect sequence: CODE (OR/AND) -> STR -> CODE (=, LIKE, <=, >=) -> STR
            if (
                idx + 3 < len(chunks)
                and chunks[idx + 1][0] == "STR"
                and chunks[idx + 2][0] == "CODE"
                and re.match(r"^\s*(?:=|LIKE|<=|>=)\s*$", chunks[idx + 2][1], re.IGNORECASE)
                and chunks[idx + 3][0] == "STR"
            ):
                str1 = chunks[idx + 1][1][1:-1]
                str2 = chunks[idx + 3][1][1:-1]
                if str1 == str2:
                    return False, "Boolean/Tautology injection detected: tautological string comparison"

    return True, "SAFE"
