import threading
from typing import Dict, List


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0) -> None:
        self.max_connections: int = max_connections
        self.ping_timeout: float = ping_timeout
        self._lock: threading.Lock = threading.Lock()
        self._next_id: int = 1
        self._closed: bool = False
        self._in_use: Dict[int, dict] = {}
        self._pool: List[dict] = [
            self._create_connection() for _ in range(max(0, max_connections))
        ]

    def _create_connection(self) -> dict:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if self._closed or not self._pool:
                raise RuntimeError("Pool exhausted")
            conn = self._pool.pop(0)
            self._in_use[conn["id"]] = conn
            return conn

    def release(self, conn: dict) -> None:
        if not isinstance(conn, dict):
            return
        with self._lock:
            conn_id = conn.get("id")
            if conn_id is not None:
                self._in_use.pop(conn_id, None)
            if self._closed:
                conn["alive"] = False
                return
            if any(c.get("id") == conn_id for c in self._pool):
                return
            if len(self._pool) < self.max_connections:
                self._pool.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            if self._closed:
                return 0
            healed = 0
            for i in range(len(self._pool)):
                if not self._pool[i].get("alive", False):
                    self._pool[i] = self._create_connection()
                    healed += 1
            return healed

    def close_all(self) -> None:
        with self._lock:
            self._closed = True
            for conn in self._pool:
                conn["alive"] = False
            for conn in self._in_use.values():
                conn["alive"] = False
            self._pool.clear()
            self._in_use.clear()
