import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    """Prunes unused imports and dead top-level private functions from source code using AST."""
    tree = ast.parse(source_code, type_comments=True)

    def extract_all_exported_names(t: ast.AST) -> set[str]:
        """Extracts string identifiers exported via __all__ definitions."""
        exported: set[str] = set()
        for node in ast.walk(t):
            is_all_target = False
            val_node = None
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name) and target.id == "__all__":
                        is_all_target = True
                val_node = node.value
            elif isinstance(node, ast.AnnAssign):
                if isinstance(node.target, ast.Name) and node.target.id == "__all__":
                    is_all_target = True
                val_node = node.value
            elif isinstance(node, ast.AugAssign):
                if isinstance(node.target, ast.Name) and node.target.id == "__all__":
                    is_all_target = True
                val_node = node.value
            elif isinstance(node, ast.Call):
                if (
                    isinstance(node.func, ast.Attribute)
                    and isinstance(node.func.value, ast.Name)
                    and node.func.value.id == "__all__"
                    and node.func.attr in ("append", "extend")
                ):
                    is_all_target = True
                    val_node = node

            if is_all_target and val_node is not None:
                for sub in ast.walk(val_node):
                    if isinstance(sub, ast.Constant) and isinstance(sub.value, str):
                        exported.add(sub.value)
        return exported

    def get_referenced_names(root_node: ast.AST) -> set[str]:
        """Collects all identifier names referenced within an AST node."""
        names: set[str] = set()
        for n in ast.walk(root_node):
            if isinstance(n, ast.Name):
                names.add(n.id)
            elif isinstance(n, (ast.Global, ast.Nonlocal)):
                names.update(n.names)
            elif isinstance(n, (ast.arg, ast.FunctionDef, ast.AsyncFunctionDef, ast.AnnAssign)):
                ann = getattr(n, "annotation", None) or getattr(n, "returns", None)
                if ann is not None:
                    for sub in ast.walk(ann):
                        if isinstance(sub, ast.Constant) and isinstance(sub.value, str):
                            try:
                                sub_tree = ast.parse(sub.value, mode="eval")
                                for sn in ast.walk(sub_tree):
                                    if isinstance(sn, ast.Name):
                                        names.add(sn.id)
                            except Exception:
                                pass
            tc = getattr(n, "type_comment", None)
            if tc and isinstance(tc, str):
                for mode in ("eval", "func_type"):
                    try:
                        tc_tree = ast.parse(tc, mode=mode)
                        for sn in ast.walk(tc_tree):
                            if isinstance(sn, ast.Name):
                                names.add(sn.id)
                        break
                    except Exception:
                        pass
        return names

    # 1. Prune dead top-level private functions via reachability analysis
    private_fns: dict[str, list[ast.AST]] = {}
    roots: list[ast.AST] = []

    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
            private_fns.setdefault(stmt.name, []).append(stmt)
        elif not isinstance(stmt, (ast.Import, ast.ImportFrom)):
            # Public functions, class definitions, assignments, expressions/docstrings, etc.
            roots.append(stmt)

    initial_names = set()
    for root in roots:
        initial_names.update(get_referenced_names(root))
    initial_names.update(extract_all_exported_names(tree))

    visited_private_names: set[str] = set()
    queue = [name for name in initial_names if name in private_fns]
    visited_private_names.update(queue)

    while queue:
        curr_name = queue.pop(0)
        for fn_node in private_fns[curr_name]:
            for ref in get_referenced_names(fn_node):
                if ref in private_fns and ref not in visited_private_names:
                    visited_private_names.add(ref)
                    queue.append(ref)

    # Filter out dead private functions from top-level body
    new_body = []
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
            if stmt.name in visited_private_names:
                new_body.append(stmt)
        else:
            new_body.append(stmt)
    tree.body = new_body

    # 2. Prune unused imports across the remaining AST
    all_referenced_names = set()
    for stmt in tree.body:
        if not isinstance(stmt, (ast.Import, ast.ImportFrom)):
            all_referenced_names.update(get_referenced_names(stmt))
    all_referenced_names.update(extract_all_exported_names(tree))

    class ImportPruner(ast.NodeTransformer):
        def visit_Import(self, node: ast.Import):
            kept_names = []
            for alias_node in node.names:
                bound_name = (
                    alias_node.asname
                    if alias_node.asname
                    else alias_node.name.split(".")[0]
                )
                if bound_name in all_referenced_names:
                    kept_names.append(alias_node)
            if not kept_names:
                return None
            node.names = kept_names
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom):
            if node.module == "__future__":
                return node
            kept_names = []
            for alias_node in node.names:
                if alias_node.name == "*":
                    kept_names.append(alias_node)
                else:
                    bound_name = (
                        alias_node.asname if alias_node.asname else alias_node.name
                    )
                    if bound_name in all_referenced_names:
                        kept_names.append(alias_node)
            if not kept_names:
                return None
            node.names = kept_names
            return node

        def generic_visit(self, node: ast.AST):
            super().generic_visit(node)
            # Ensure block bodies do not become empty after statement removal
            for body_attr in ("body",):
                if hasattr(node, body_attr):
                    body_list = getattr(node, body_attr)
                    if isinstance(body_list, list) and len(body_list) == 0 and not isinstance(node, ast.Module):
                        setattr(node, body_attr, [ast.Pass()])
            try_types = (ast.Try, ast.TryStar) if hasattr(ast, "TryStar") else (ast.Try,)
            if isinstance(node, try_types):
                if not node.handlers and not node.finalbody:
                    node.finalbody = [ast.Pass()]
            return node

    tree = ImportPruner().visit(tree)
    ast.fix_missing_locations(tree)

    result = ast.unparse(tree)
    compile(result, "<string>", "exec")
    return result
