class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected."""
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        if not dependencies:
            return []

        # Collect all tasks, including any referenced in dependency lists
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        # Build in-degrees (number of dependencies) and dependents graph
        in_degrees: dict[str, int] = {task: 0 for task in all_tasks}
        dependents: dict[str, list[str]] = {task: [] for task in all_tasks}

        for task, deps in dependencies.items():
            unique_deps = set(deps)
            in_degrees[task] = len(unique_deps)
            for dep in unique_deps:
                dependents[dep].append(task)

        # Stage 0 contains all tasks with no dependencies
        current_stage = [task for task, degree in in_degrees.items() if degree == 0]

        stages: list[list[str]] = []
        resolved_count = 0

        while current_stage:
            current_stage.sort()
            stages.append(current_stage)
            resolved_count += len(current_stage)

            next_stage: list[str] = []
            for task in current_stage:
                for dependent in dependents[task]:
                    in_degrees[dependent] -= 1
                    if in_degrees[dependent] == 0:
                        next_stage.append(dependent)

            current_stage = next_stage

        if resolved_count != len(all_tasks):
            raise CircularDependencyError("Circular dependency detected.")

        return stages
