import ast
from typing import Iterable, Set


def prune_dead_code_and_imports(source_code: str) -> str:
    """Prunes unused imports and unreferenced top-level private functions

    from Python source code while preserving module docstrings, classes,
    and global variable assignments.
    """
    tree = ast.parse(source_code)

    def get_bound_name(alias_node: ast.alias) -> str:
        """Returns the local symbol name bound by an import alias."""
        if alias_node.asname:
            return alias_node.asname
        return alias_node.name.split('.')[0]

    def get_all_references(nodes: Iterable[ast.AST]) -> Set[str]:
        """Collects all identifier references within the given AST nodes."""
        refs: Set[str] = set()
        for node in nodes:
            for child in ast.walk(node):
                if isinstance(child, ast.Name):
                    refs.add(child.id)
                elif isinstance(child, (ast.Global, ast.Nonlocal)):
                    refs.update(child.names)
                elif isinstance(child, ast.Assign):
                    for target in child.targets:
                        if isinstance(target, ast.Name) and target.id == '__all__':
                            if isinstance(
                                child.value, (ast.List, ast.Tuple, ast.Set)
                            ):
                                for elt in child.value.elts:
                                    if isinstance(
                                        elt, ast.Constant
                                    ) and isinstance(elt.value, str):
                                        refs.add(elt.value)
        return refs

    # Iteratively prune until no further dead functions or imports can be removed
    while True:
        modified = False

        # 1. Prune dead top-level private functions (starts with '_')
        new_body = []
        for stmt in tree.body:
            if isinstance(
                stmt, (ast.FunctionDef, ast.AsyncFunctionDef)
            ) and stmt.name.startswith('_'):
                other_stmts = [s for s in tree.body if s is not stmt]
                refs = get_all_references(other_stmts)
                if stmt.name not in refs:
                    modified = True
                    continue
            new_body.append(stmt)
        tree.body = new_body

        # 2. Prune unused imports across the AST
        used_names = get_all_references(tree.body)

        class ImportPruner(ast.NodeTransformer):

            def __init__(self) -> None:
                self.changed = False

            def visit_Import(self, node: ast.Import):
                kept = [
                    alias
                    for alias in node.names
                    if get_bound_name(alias) in used_names
                ]
                if len(kept) != len(node.names):
                    self.changed = True
                if not kept:
                    return None
                node.names = kept
                return node

            def visit_ImportFrom(self, node: ast.ImportFrom):
                kept = [
                    alias
                    for alias in node.names
                    if alias.name == '*' or get_bound_name(alias) in used_names
                ]
                if len(kept) != len(node.names):
                    self.changed = True
                if not kept:
                    return None
                node.names = kept
                return node

        pruner = ImportPruner()
        tree = pruner.visit(tree)
        if pruner.changed:
            modified = True

        if not modified:
            break

    return ast.unparse(tree)
