class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected."""

    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        """Resolves dependencies into execution stages.

        Args:
            dependencies: Mapping of task_name -> list of task_names it depends on.

        Returns:
            List of stages, where each stage is a sorted list of task names
            that can execute in parallel.

        Raises:
            CircularDependencyError: If a circular dependency exists.
        """
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        in_degree = {task: 0 for task in all_tasks}
        dependents = {task: set() for task in all_tasks}

        for task, deps in dependencies.items():
            unique_deps = set(deps)
            in_degree[task] = len(unique_deps)
            for dep in unique_deps:
                dependents[dep].add(task)

        current_stage = sorted(
            [task for task in all_tasks if in_degree[task] == 0]
        )
        stages = []
        processed_count = 0

        while current_stage:
            stages.append(current_stage)
            processed_count += len(current_stage)
            next_stage = []
            for task in current_stage:
                for dependent in dependents[task]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_stage.append(dependent)
            current_stage = sorted(next_stage)

        if processed_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected")

        return stages
