import asyncio
import inspect
from typing import Optional, Callable, Any


class AsyncWorkerPool:
    """An asynchronous worker pool using standard asyncio.

    Supports task prioritization (higher integer priority runs first), FIFO ordering for equal
    priorities, bounded queue capacity, clean shutdown (with or without draining), timeout safety,
    and exception propagation via returned futures.
    """

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size <= 0:
            raise ValueError("max_queue_size must be greater than 0")

        self._concurrency: int = concurrency
        self._max_queue_size: int = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: list[asyncio.Task] = []
        self._started: bool = False
        self._is_shutting_down: bool = False
        self._counter: int = 0

    async def start(self) -> None:
        """Spawns the worker tasks."""
        if self._started:
            return
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")
        self._started = True
        self._workers = [
            asyncio.create_task(self._worker_loop())
            for _ in range(self._concurrency)
        ]

    async def submit(
        self,
        coro_func: Callable[..., Any],
        *args: Any,
        priority: int = 0,
        **kwargs: Any
    ) -> asyncio.Future:
        """Enqueues a coroutine function (or callable) to be executed by pool workers.

        - Higher integer priority executes before lower integer priority.
        - Equal priorities are executed in FIFO order.
        - Returns an asyncio.Future that resolves with the result or exception.
        - Raises RuntimeError if the pool is shutting down.
        """
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        if not self._started:
            await self.start()

        loop = asyncio.get_running_loop()
        fut: asyncio.Future = loop.create_future()

        self._counter += 1
        # asyncio.PriorityQueue is a min-heap. Invert priority (-priority) so higher values pop first.
        # Counter breaks ties in FIFO order for equal priorities and prevents comparing uncomparable objects.
        item = (-priority, self._counter, fut, coro_func, args, kwargs)

        try:
            await self._queue.put(item)
        except Exception:
            if not fut.done():
                fut.cancel()
            raise

        if self._is_shutting_down:
            if not fut.done():
                fut.cancel()
            raise RuntimeError("Pool is shutting down")

        return fut

    async def _worker_loop(self) -> None:
        """Internal loop executed by each worker task."""
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            _, _, fut, coro_func, args, kwargs = item

            if fut.cancelled():
                self._queue.task_done()
                continue

            try:
                res = coro_func(*args, **kwargs)
                if inspect.isawaitable(res):
                    res = await res
                if not fut.done():
                    fut.set_result(res)
            except asyncio.CancelledError:
                if not fut.done():
                    fut.cancel()
                raise
            except Exception as exc:
                if not fut.done():
                    fut.set_exception(exc)
            except BaseException as exc:
                if not fut.done():
                    fut.set_exception(exc)
                raise
            finally:
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """Shuts down the worker pool.

        - If drain=True, waits for all enqueued tasks to finish.
        - If drain=False, cancels queued and executing tasks immediately.
        - Respects optional timeout in seconds.
        """
        if self._is_shutting_down:
            return
        self._is_shutting_down = True

        async def _do_shutdown() -> None:
            if drain:
                # Wait until all currently enqueued items are processed
                await self._queue.join()
                # Stop workers by cancelling idle worker tasks waiting on queue.get()
                for w in self._workers:
                    w.cancel()
                await asyncio.gather(*self._workers, return_exceptions=True)
            else:
                # Cancel queued tasks immediately
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        _, _, fut, _, _, _ = item
                        if not fut.done():
                            fut.cancel()
                        self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break

                # Cancel running workers
                for w in self._workers:
                    w.cancel()
                await asyncio.gather(*self._workers, return_exceptions=True)

        try:
            if timeout is not None:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            else:
                await _do_shutdown()
        except (asyncio.TimeoutError, TimeoutError):
            # Guarantee full cleanup on timeout
            for w in self._workers:
                w.cancel()
            await asyncio.gather(*self._workers, return_exceptions=True)

            while not self._queue.empty():
                try:
                    item = self._queue.get_nowait()
                    _, _, fut, _, _, _ = item
                    if not fut.done():
                        fut.cancel()
                    self._queue.task_done()
                except asyncio.QueueEmpty:
                    break
            raise
