from typing import Any


class QuorumCluster:

    def __init__(self, node_ids: list[str]):
        """Initializes cluster state with unique node IDs and calculates quorum threshold."""
        self.node_ids = list(node_ids)
        self.n = len(self.node_ids)
        self.quorum_threshold = self.n // 2 + 1
        self.nodes: dict[str, dict[str, Any]] = {
            node_id: {} for node_id in self.node_ids
        }
        self.committed_state: dict[str, Any] = {}
        self.current_partitions: list[set[str]] = [set(self.node_ids)]

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """Divides cluster into isolated network partitions."""
        set_a = set(group_a)
        set_b = set(group_b)
        self.current_partitions = [set_a, set_b]
        assigned_nodes = set_a | set_b
        for node_id in self.node_ids:
            if node_id not in assigned_nodes:
                self.current_partitions.append({node_id})

    def heal_partition(self) -> None:
        """Restores full connectivity and synchronizes committed state across all nodes."""
        self.current_partitions = [set(self.node_ids)]
        for node_id in self.node_ids:
            self.nodes[node_id] = dict(self.committed_state)

    def _get_partition(self, node_id: str) -> set[str]:
        """Finds the active partition set containing node_id."""
        for partition_set in self.current_partitions:
            if node_id in partition_set:
                return partition_set
        return {node_id}

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """Proposes a write from from_node.

        Commits the write if from_node belongs to a majority partition; otherwise rejects it.
        """
        if from_node not in self.nodes:
            return False

        active_partition = self._get_partition(from_node)

        if len(active_partition) >= self.quorum_threshold:
            self.committed_state[key] = value
            for node_id in active_partition:
                if node_id in self.nodes:
                    self.nodes[node_id][key] = value
            return True

        return False

    def read_value(self, from_node: str, key: str) -> Any:
        """Returns the committed value for key on from_node (or None if not set)."""
        if from_node in self.nodes:
            return self.nodes[from_node].get(key, None)
        return None
