import struct
import zlib


class BinaryFrameParser:
    """Parser for binary network frames with magic marker, length header, and CRC32 checksum."""

    MAGIC: bytes = b"SX"
    HEADER_SIZE: int = 8  # 2 bytes magic + 2 bytes type + 4 bytes payload length
    MIN_FRAME_SIZE: int = (
        12  # 2 bytes magic + 2 bytes type + 4 bytes payload length + 4 bytes CRC
    )

    def __init__(self, max_payload_size: int | None = None) -> None:
        self._buffer: bytearray = bytearray()
        self.max_payload_size: int | None = max_payload_size

    def _is_valid_frame(self, offset: int) -> bool:
        """Check if a complete, CRC32-verified frame exists at the given buffer offset."""
        buf = self._buffer
        if len(buf) - offset < self.MIN_FRAME_SIZE:
            return False

        msg_type, payload_len = struct.unpack_from(">HI", buf, offset + 2)
        if (
            self.max_payload_size is not None
            and payload_len > self.max_payload_size
        ):
            return False

        total_len = self.MIN_FRAME_SIZE + payload_len
        if len(buf) - offset < total_len:
            return False

        expected_crc = struct.unpack_from(">I", buf, offset + 8 + payload_len)[
            0
        ]
        crc_data = buf[offset + 2 : offset + 8 + payload_len]
        calc_crc = zlib.crc32(crc_data) & 0xFFFFFFFF
        return calc_crc == expected_crc

    def feed(self, data: bytes) -> list[tuple[int, bytes]]:
        """Ingests an arbitrary chunk of incoming bytes and returns all parsed and CRC32-verified packets."""
        if data:
            self._buffer.extend(data)

        packets: list[tuple[int, bytes]] = []

        while True:
            # Resynchronize if buffer doesn't start with magic header 'SX'
            if len(self._buffer) < 2:
                if len(self._buffer) == 1 and self._buffer != b"S":
                    self._buffer.clear()
                break

            if not self._buffer.startswith(self.MAGIC):
                idx = self._buffer.find(self.MAGIC)
                if idx != -1:
                    del self._buffer[:idx]
                else:
                    if self._buffer.endswith(b"S"):
                        del self._buffer[:-1]
                    else:
                        self._buffer.clear()
                    break

            # Need at least HEADER_SIZE (8 bytes) to unpack message type & payload length
            if len(self._buffer) < self.HEADER_SIZE:
                break

            msg_type, payload_len = struct.unpack_from(">HI", self._buffer, 2)

            # Optional payload size boundary check
            if (
                self.max_payload_size is not None
                and payload_len > self.max_payload_size
            ):
                del self._buffer[:1]
                continue

            total_len = self.MIN_FRAME_SIZE + payload_len

            # Check if complete frame data has arrived
            if len(self._buffer) < total_len:
                # Disambiguate corrupted header with huge payload length vs. legitimate partial frame:
                # If a subsequent 'SX' marker in the buffer forms a complete verified valid frame,
                # the current candidate at index 0 must be corrupted noise.
                found_later_valid = False
                search_pos = 2
                while True:
                    next_idx = self._buffer.find(self.MAGIC, search_pos)
                    if next_idx == -1:
                        break
                    if self._is_valid_frame(next_idx):
                        found_later_valid = True
                        break
                    search_pos = next_idx + 1

                if found_later_valid:
                    del self._buffer[:1]
                    continue
                else:
                    break

            # Verify CRC32 checksum over (type_bytes + length_bytes + payload)
            expected_crc = struct.unpack_from(
                ">I", self._buffer, 8 + payload_len
            )[0]
            crc_data = self._buffer[2 : 8 + payload_len]
            calc_crc = zlib.crc32(crc_data) & 0xFFFFFFFF

            if calc_crc == expected_crc:
                payload = bytes(self._buffer[8 : 8 + payload_len])
                packets.append((msg_type, payload))
                del self._buffer[:total_len]
            else:
                # CRC mismatch: advance by 1 byte to attempt resynchronization
                del self._buffer[:1]

        return packets
