import re


def is_safe_sql_query(query: str) -> tuple[bool, str]:
    """
    Inspects a SQL query string to determine if it is safe or contains malicious SQL injection signatures.

    Returns:
        (True, "SAFE") if the query is safe.
        (False, "REASON") if malicious SQL injection patterns are detected.
    """
    if not isinstance(query, str) or not query.strip():
        return (True, "SAFE")

    raw_query = query.strip()

    # --- 1. Obfuscation / Inline Comment Evasion ---
    # MySQL executable comment syntax /*! ... */
    if re.search(r"/\*!", raw_query):
        return (False, "Obfuscation / inline comment evasion detected")

    # Inline comments embedded within tokens or expressions (e.g., UN/**/ION, SE/*foo*/ECT, 1/*test*/=1)
    if (
        re.search(r"\w/\*[\s\S]*?\*/\w", raw_query)
        or re.search(r"\d/\*[\s\S]*?\*/[=<>!]", raw_query)
        or re.search(r"[=<>!]/\*[\s\S]*?\*/\d", raw_query)
    ):
        return (False, "Obfuscation / inline comment evasion detected")

    # Check if stripping inline comments forms hidden keywords or tautologies
    collapsed_query = re.sub(r"/\*[\s\S]*?\*/", "", raw_query)
    forbidden_keywords = [
        r"\bUNION\b",
        r"\bSELECT\b",
        r"\bEXEC\b",
        r"\bDROP\b",
        r"\bDELETE\b",
        r"\bPG_SLEEP\b",
        r"\bBENCHMARK\b",
        r"\bWAITFOR\b",
    ]
    for kw in forbidden_keywords:
        if re.search(kw, collapsed_query, re.IGNORECASE) and not re.search(
            kw, raw_query, re.IGNORECASE
        ):
            return (False, "Obfuscation / inline comment evasion detected")

    if re.search(r"\b\d+\s*=\s*\d+\b", collapsed_query) and not re.search(
        r"\b\d+\s*=\s*\d+\b", raw_query
    ):
        return (False, "Obfuscation / inline comment evasion detected")

    # --- Dequoting Helper ---
    # Replaces contents of quoted strings with placeholders so string text is ignored during structural analysis
    def mask_strings_and_comments(sql: str):
        i = 0
        n = len(sql)
        out = []
        unbalanced = False

        while i < n:
            # Multi-line comment /* ... */
            if sql[i : i + 2] == "/*":
                end = sql.find("*/", i + 2)
                if end == -1:
                    i = n
                else:
                    i = end + 2
                out.append(" ")
                continue

            # Single-line comment (-- or #)
            if sql[i : i + 2] == "--" or sql[i] == "#":
                end = sql.find("\n", i)
                if end == -1:
                    i = n
                else:
                    i = end + 1
                out.append(" ")
                continue

            # Quoted strings ('...' or "...")
            if sql[i] in ("'", '"'):
                q = sql[i]
                i += 1
                closed = False
                while i < n:
                    if sql[i] == "\\" and i + 1 < n:
                        i += 2
                        continue
                    if sql[i] == q:
                        if i + 1 < n and sql[i + 1] == q:
                            i += 2
                            continue
                        closed = True
                        i += 1
                        break
                    i += 1
                if not closed:
                    unbalanced = True
                out.append(" _STR_ ")
                continue

            out.append(sql[i])
            i += 1

        return "".join(out), unbalanced

    dequoted, unbalanced_quotes = mask_strings_and_comments(raw_query)

    # --- 2. Stacked Query Execution ---
    clean_dequoted = dequoted.rstrip()
    if clean_dequoted.endswith(";"):
        clean_dequoted = clean_dequoted[:-1].rstrip()

    if ";" in clean_dequoted:
        if re.search(
            r";\s*(?:DROP|EXEC|DELETE|SELECT|UPDATE|INSERT|TRUNCATE|ALTER|CREATE|GRANT|REVOKE|SHUTDOWN|DECLARE|SET|MERGE|CALL|XP_\w+|\w+)",
            clean_dequoted,
            re.IGNORECASE,
        ):
            return (False, "Stacked query execution detected")

    # --- 3. UNION-based Data Exfiltration ---
    if re.search(
        r"\bUNION\b[\s\(\)]*(?:ALL|DISTINCT)?[\s\(\)]*SELECT\b",
        dequoted,
        re.IGNORECASE,
    ) or re.search(r"\bUNION\b[\s\S]*?\bSELECT\b", dequoted, re.IGNORECASE):
        return (False, "UNION-based data exfiltration detected")

    # --- 4. Time-based Blind Execution ---
    time_based_patterns = [
        r"\bPG_SLEEP\s*\(",
        r"\bWAITFOR\s+DELAY\b",
        r"\bBENCHMARK\s*\(",
        r"\bSLEEP\s*\(",
        r"\bDBMS_LOCK\.SLEEP\s*\(",
        r"\bDBMS_PIPE\.RECEIVE_MESSAGE\s*\(",
    ]
    for pat in time_based_patterns:
        if re.search(pat, dequoted, re.IGNORECASE):
            return (False, "Time-based blind execution detected")

    # --- 5. Boolean/Tautology Injection ---
    # Quote breakout + comment (e.g. admin'--, admin' #, admin'/*)
    if re.search(r"['\"]\s*(?:--|#|/\*)", raw_query):
        return (False, "Boolean/Tautology injection detected")

    # Quote breakout + logical operator (e.g. ' OR ..., " OR ..., 1' AND ...)
    if re.search(
        r"^['\"]?\w*['\"]\s*\b(?:OR|AND)\b", raw_query, re.IGNORECASE
    ) or re.search(r"^['\"]\s*\b(?:OR|AND)\b", raw_query, re.IGNORECASE):
        return (False, "Boolean/Tautology injection detected")

    # String equality tautologies: 'X' = 'X' or "X" = "X"
    str_eq_pattern = r"(?:'([^'\\]*(?:\\.[^'\\]*)*)'|\"([^\"\\]*(?:\\.[^\"\\]*)*)\")\s*(?:=|\bLIKE\b)\s*(?:'([^'\\]*(?:\\.[^'\\]*)*)'|\"([^\"\\]*(?:\\.[^\"\\]*)*)\")"
    for m in re.finditer(str_eq_pattern, raw_query, re.IGNORECASE):
        g = m.groups()
        val1 = g[0] if g[0] is not None else g[1]
        val2 = g[2] if g[2] is not None else g[3]
        if val1 == val2:
            start_pos = m.start()
            prefix = raw_query[:start_pos].rstrip()
            if not (prefix.endswith("->") or prefix.endswith("->>")):
                return (False, "Boolean/Tautology injection detected")

    # Number tautologies: 1 = 1, 0 = 0
    num_eq_pattern = r"\b(?P<v1>\d+)\s*(?:=|\bLIKE\b)\s*(?P<v2>\d+)\b"
    for m in re.finditer(num_eq_pattern, raw_query, re.IGNORECASE):
        if m.group("v1") == m.group("v2"):
            return (False, "Boolean/Tautology injection detected")

    # Boolean tautologies: OR TRUE, AND TRUE, OR 1=1
    if re.search(r"\b(?:OR|AND)\s+(?:TRUE|1=1|0=0)\b", dequoted, re.IGNORECASE):
        return (False, "Boolean/Tautology injection detected")

    if unbalanced_quotes and ("'" in raw_query or '"' in raw_query):
        return (False, "Boolean/Tautology injection detected")

    return (True, "SAFE")
