import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    """
    Refactors Python source code using the AST module by pruning:
    1. Unused import statements and unused imported names from composite from-imports.
    2. Dead top-level private functions (functions starting with '_') that are not referenced
       anywhere in reachable code.

    Preserves module docstrings, class definitions, global variable assignments, public functions,
    and returns syntactically valid Python code verified with compile().
    """
    tree = ast.parse(source_code)

    def get_bound_name(alias: ast.alias, is_import_from: bool = False) -> str:
        if alias.name == '*':
            return '*'
        if alias.asname:
            return alias.asname
        if is_import_from:
            return alias.name
        return alias.name.split('.')[0]

    def get_loaded_names(node: ast.AST) -> set[str]:
        names = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name) and isinstance(child.ctx, ast.Load):
                names.add(child.id)
        return names

    def extract_all_strings(tree_node: ast.AST) -> set[str]:
        strings = set()
        for node in ast.walk(tree_node):
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name) and target.id == '__all__':
                        for n in ast.walk(node.value):
                            if isinstance(n, ast.Constant) and isinstance(n.value, str):
                                strings.add(n.value)
            elif isinstance(node, ast.AugAssign):
                if isinstance(node.target, ast.Name) and node.target.id == '__all__':
                    for n in ast.walk(node.value):
                        if isinstance(n, ast.Constant) and isinstance(n.value, str):
                            strings.add(n.value)
            elif isinstance(node, ast.Call):
                if (
                    isinstance(node.func, ast.Attribute)
                    and isinstance(node.func.value, ast.Name)
                    and node.func.value.id == '__all__'
                ):
                    for n in ast.walk(node):
                        if isinstance(n, ast.Constant) and isinstance(n.value, str):
                            strings.add(n.value)
        return strings

    top_private_funcs = {}
    roots = []

    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if stmt.name.startswith('_'):
                top_private_funcs[stmt.name] = stmt
            else:
                roots.append(stmt)
        elif isinstance(stmt, (ast.Import, ast.ImportFrom)):
            pass
        else:
            roots.append(stmt)

    reachable_names = extract_all_strings(tree)
    for root in roots:
        reachable_names.update(get_loaded_names(root))

    worklist = list(reachable_names)
    while worklist:
        curr = worklist.pop()
        if curr in top_private_funcs:
            func_node = top_private_funcs[curr]
            func_loaded_names = get_loaded_names(func_node)
            for name in func_loaded_names:
                if name not in reachable_names:
                    reachable_names.add(name)
                    worklist.append(name)

    class Pruner(ast.NodeTransformer):
        def visit_Module(self, node: ast.Module) -> ast.Module:
            new_body = []
            for stmt in node.body:
                if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith('_'):
                    if stmt.name not in reachable_names:
                        continue
                transformed = self.visit(stmt)
                if transformed is not None:
                    new_body.append(transformed)
            node.body = new_body
            return node

        def visit_Import(self, node: ast.Import) -> ast.Import | None:
            node.names = [
                alias
                for alias in node.names
                if get_bound_name(alias, is_import_from=False) in reachable_names
            ]
            if not node.names:
                return None
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom) -> ast.ImportFrom | None:
            node.names = [
                alias
                for alias in node.names
                if alias.name == '*' or get_bound_name(alias, is_import_from=True) in reachable_names
            ]
            if not node.names:
                return None
            return node

    pruned_tree = Pruner().visit(tree)
    ast.fix_missing_locations(pruned_tree)
    result = ast.unparse(pruned_tree)
    compile(result, '<string>', 'exec')
    return result
