import time
import threading
from collections import OrderedDict
from typing import Any, Optional

class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.default_ttl = default_ttl_seconds
        self.cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self.lock = threading.RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self.lock:
            if key in self.cache:
                self.cache.move_to_end(key)
            else:
                if len(self.cache) >= self.capacity:
                    current_time = time.time()
                    evicted = False

                    # Try to evict the oldest expired item (first one encountered from LRU side)
                    for k, (_, exp_time) in self.cache.items():
                        if current_time >= exp_time:
                            del self.cache[k]
                            evicted = True
                            break

                    # If no item was expired, evict the least recently used non-expired item
                    if not evicted:
                        self.cache.popitem(last=False)

            expiration = time.time() + (ttl if ttl is not None else self.default_ttl)
            self.cache[key] = (value, expiration)

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            if key in self.cache:
                value, exp_time = self.cache[key]
                if time.time() < exp_time:
                    self.cache.move_to_end(key)
                    return value
                else:
                    del self.cache[key]
                    return None
            return None

    def delete(self, key: str) -> bool:
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self.lock:
            current_time = time.time()
            expired_keys = [
                k for k, (_, exp_time) in self.cache.items() 
                if current_time >= exp_time
            ]
            for k in expired_keys:
                del self.cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self.lock:
            current_time = time.time()
            return sum(1 for _, exp_time in self.cache.values() if current_time < exp_time)
