class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        # Identify all tasks (keys and values)
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        # Map each task to the set of tasks it depends on
        pending_deps = {task: set() for task in all_tasks}
        for task, deps in dependencies.items():
            pending_deps[task] = set(deps)

        stages = []

        while pending_deps:
            # Find all tasks that have no pending dependencies
            current_stage = [task for task, deps in pending_deps.items() if not deps]

            # If there are tasks left but none can be resolved, we have a cycle
            if not current_stage:
                raise CircularDependencyError("Circular dependency detected")

            # Sort alphabetically to guarantee consistent ordering within the stage
            current_stage.sort()
            stages.append(current_stage)

            # Remove resolved tasks from the pending list
            for task in current_stage:
                del pending_deps[task]

            # Remove the resolved tasks from the dependency sets of remaining tasks
            for deps in pending_deps.values():
                deps.difference_update(current_stage)

        return stages
