import threading
import time
from collections import deque
from typing import Optional, Dict

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.lock = threading.Lock()
        self.history: Dict[str, deque] = {}

    def _cleanup(self, key: str, current_time: float) -> Optional[deque]:
        if key not in self.history:
            return None

        history = self.history[key]
        window_start = current_time - self.window_seconds

        # Remove requests that are older than the sliding window
        while history and history[0] <= window_start:
            history.popleft()

        # Clean up the key if there are no requests left to save memory
        if not history:
            del self.history[key]
            return None

        return history

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            history = self._cleanup(key, timestamp)

            # If the history is empty or key doesn't exist
            if history is None:
                if self.max_requests > 0:
                    self.history[key] = deque([timestamp])
                    return True, 0.0
                else:
                    return False, float('inf')

            # If we are under the limit, allow the request
            if len(history) < self.max_requests:
                history.append(timestamp)
                return True, 0.0
            else:
                # Rate limited, calculate time until the oldest request falls out of the window
                retry_after = history[0] + self.window_seconds - timestamp
                return False, max(0.0, float(retry_after))

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            history = self._cleanup(key, timestamp)
            if history is None:
                return self.max_requests
            return max(0, self.max_requests - len(history))
