Here is the complete, robust implementation of the `AsyncWorkerPool` class using standard `asyncio`. 

It uses a min-heap priority queue (where higher priority numbers are processed first by negating them), properly wraps executed coroutines, safely bubbles up exceptions to the `asyncio.Future` returned to the caller, and correctly implements gracefully bounded shutdown handling.

```python
import asyncio
import time
from typing import Any, Callable, Coroutine, Optional

class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        self.concurrency = concurrency
        self.max_queue_size = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: list[asyncio.Task] = []
        self._shutting_down = False
        self._counter = 0

    async def submit(
        self, 
        coro_func: Callable[..., Coroutine[Any, Any, Any]], 
        *args: Any, 
        priority: int = 0, 
        **kwargs: Any
    ) -> asyncio.Future:
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future = loop.create_future()
        self._counter += 1

        # PriorityQueue is a min-heap. We negate priority so higher integers pop first.
        # self._counter is used as a tie-breaker so functions themselves are not compared.
        item = (-priority, self._counter, coro_func, args, kwargs, future)
        await self._queue.put(item)

        return future

    async def start(self) -> None:
        if self._workers:
            return  # Already started
        self._shutting_down = False
        for _ in range(self.concurrency):
            task = asyncio.create_task(self._worker_loop())
            self._workers.append(task)

    async def _worker_loop(self) -> None:
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                # Worker cancelled while idle and waiting for a new task
                break

            priority, counter, coro_func, args, kwargs, future = item

            # If the caller cancelled the future before it began, skip execution entirely
            if future.cancelled():
                self._queue.task_done()
                continue

            try:
                result = await coro_func(*args, **kwargs)
                if not future.cancelled():
                    future.set_result(result)
            except asyncio.CancelledError:
                # Execution cancelled
                if not future.cancelled():
                    future.cancel()

                # Verify if the worker task itself was cancelled (e.g., via shutdown(drain=False))
                # or if the internal coroutine raised CancelledError on its own
                current_task = asyncio.current_task()
                if current_task is not None and current_task.cancelled():
                    self._queue.task_done()
                    break
            except Exception as e:
                # Catch any standard exception and pipe it back to the submit caller
                if not future.cancelled():
                    future.set_exception(e)

            self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        self._shutting_down = True
        start_time = time.monotonic()

        if drain:
            try:
                if timeout is None:
                    await self._queue.join()
                else:
                    await asyncio.wait_for(self._queue.join(), timeout=timeout)
            except asyncio.TimeoutError:
                # Timeout exhausted while draining. Fallthrough to force-clean.
                pass

        # Flush the remainder of the queue and cancel unstarted futures
        while not self._queue.empty():
            try:
                item = self._queue.get_nowait()
                future = item[-1]
                if not future.cancelled():
                    future.cancel()
                self._queue.task_done()
            except asyncio.QueueEmpty:
                break

        # Cancel executing workers
        for task in self._workers:
            task.cancel()

        # Wait for all workers to cleanly exit
        if self._workers:
            if timeout is None:
                await asyncio.gather(*self._workers, return_exceptions=True)
            else:
                elapsed = time.monotonic() - start_time
                remaining = max(0.0, timeout - elapsed)
                try:
                    await asyncio.wait_for(
                        asyncio.gather(*self._workers, return_exceptions=True),
                        timeout=remaining
                    )
                except asyncio.TimeoutError:
                    pass

        self._workers.clear()
