class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._next_id = 1
        self._pool = []
        self._available = []

        for _ in range(max_connections):
            conn = self._create_connection()
            self._pool.append(conn)
            self._available.append(conn)

    def _create_connection(self) -> dict:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        if not self._available:
            raise RuntimeError("Pool exhausted")
        return self._available.pop(0)

    def release(self, conn: dict) -> None:
        # Only accept back connections that belong to the current pool 
        # and aren't already available.
        if conn in self._pool and conn not in self._available:
            self._available.append(conn)

    def health_check_and_heal(self) -> int:
        healed_count = 0
        for i in range(len(self._pool)):
            if not self._pool[i]["alive"]:
                new_conn = self._create_connection()
                old_conn = self._pool[i]
                self._pool[i] = new_conn

                if old_conn in self._available:
                    # Replace the dead connection directly in the available list
                    idx = self._available.index(old_conn)
                    self._available[idx] = new_conn
                else:
                    # If the dead connection was acquired by a client, we replenish 
                    # the pool with the new connection immediately.
                    self._available.append(new_conn)

                healed_count += 1
        return healed_count

    def close_all(self) -> None:
        for conn in self._pool:
            conn["alive"] = False
        self._pool.clear()
        self._available.clear()
