import ast

class ReferenceCollector(ast.NodeVisitor):
    def __init__(self):
        self.used_names = set()

    def visit_Name(self, node):
        # Collecting Load and Del contexts accurately tracks actual references.
        # We ignore Store contexts which represent definitions/assignments.
        if isinstance(node.ctx, (ast.Load, ast.Del)):
            self.used_names.add(node.id)
        self.generic_visit(node)

    def visit_Global(self, node):
        self.used_names.update(node.names)
        self.generic_visit(node)

    def visit_Nonlocal(self, node):
        self.used_names.update(node.names)
        self.generic_visit(node)

    def visit_Assign(self, node):
        # Keep track of names exported via __all__
        for target in node.targets:
            if isinstance(target, ast.Name) and target.id == '__all__':
                if isinstance(node.value, (ast.List, ast.Tuple, ast.Set)):
                    for elt in node.value.elts:
                        if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                            self.used_names.add(elt.value)
        self.generic_visit(node)

    def visit_AnnAssign(self, node):
        if isinstance(node.target, ast.Name) and node.target.id == '__all__':
            if node.value and isinstance(node.value, (ast.List, ast.Tuple, ast.Set)):
                for elt in node.value.elts:
                    if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                        self.used_names.add(elt.value)
        self.generic_visit(node)


class Pruner(ast.NodeTransformer):
    def __init__(self, used_names):
        self.used_names = used_names
        self.scope_level = 0

    def visit_FunctionDef(self, node):
        is_top_level = (self.scope_level == 0)

        self.scope_level += 1
        self.generic_visit(node)
        self.scope_level -= 1

        if is_top_level and node.name.startswith('_') and node.name not in self.used_names:
            return None

        return node

    def visit_AsyncFunctionDef(self, node):
        is_top_level = (self.scope_level == 0)

        self.scope_level += 1
        self.generic_visit(node)
        self.scope_level -= 1

        if is_top_level and node.name.startswith('_') and node.name not in self.used_names:
            return None

        return node

    def visit_ClassDef(self, node):
        self.scope_level += 1
        self.generic_visit(node)
        self.scope_level -= 1
        return node

    def visit_Import(self, node):
        new_names = []
        for alias in node.names:
            # If `import os.path`, the imported name in namespace is `os`. 
            # If `import xml.etree.ElementTree as ET`, it is `ET`.
            name_to_check = alias.asname if alias.asname else alias.name.split('.')[0]
            if name_to_check in self.used_names:
                new_names.append(alias)

        if not new_names:
            return None
        node.names = new_names
        return node

    def visit_ImportFrom(self, node):
        # We must never remove compiler directives like `from __future__ import annotations`
        if node.module == '__future__':
            return node

        new_names = []
        for alias in node.names:
            if alias.name == '*':
                new_names.append(alias)
                continue

            name_to_check = alias.asname if alias.asname else alias.name
            if name_to_check in self.used_names:
                new_names.append(alias)

        if not new_names:
            return None
        node.names = new_names
        return node

    def generic_visit(self, node):
        super().generic_visit(node)

        # Ensure we don't leave empty bodies, which cause syntax errors when compiling
        if hasattr(node, 'body') and not isinstance(node, ast.Module):
            if isinstance(node.body, list) and not node.body:
                node.body.append(ast.Pass())

        # Try/TryStar nodes must have at least one except block or a finally block
        if type(node).__name__ in ('Try', 'TryStar'):
            if isinstance(getattr(node, 'finalbody', None), list) and not node.handlers and not node.finalbody:
                node.finalbody.append(ast.Pass())

        return node


def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    # Pass 1: Collect referenced names accurately across the module
    collector = ReferenceCollector()
    collector.visit(tree)

    # Pass 2: Prune unreferenced private functions and imports
    pruner = Pruner(collector.used_names)
    pruner.visit(tree)

    ast.fix_missing_locations(tree)
    return ast.unparse(tree)
