from __future__ import annotations

import time
from collections import OrderedDict
from threading import RLock
from typing import Any, Optional


class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("capacity must be greater than 0")
        if default_ttl_seconds < 0:
            raise ValueError("default_ttl_seconds must be non-negative")

        self._capacity = capacity
        self._default_ttl_seconds = default_ttl_seconds
        self._cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self._lock = RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        if ttl is not None and ttl < 0:
            raise ValueError("ttl must be non-negative")

        with self._lock:
            now = time.monotonic()
            expires_at = now + (
                self._default_ttl_seconds if ttl is None else ttl
            )

            if key in self._cache:
                self._cache[key] = (value, expires_at)
                self._cache.move_to_end(key)
                return

            if len(self._cache) >= self._capacity:
                expired_key = next(
                    (
                        existing_key
                        for existing_key, (_, existing_expires_at) in self._cache.items()
                        if existing_expires_at <= now
                    ),
                    None,
                )

                if expired_key is not None:
                    del self._cache[expired_key]
                else:
                    self._cache.popitem(last=False)

            self._cache[key] = (value, expires_at)

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            item = self._cache.get(key)
            if item is None:
                return None

            value, expires_at = item
            if expires_at <= time.monotonic():
                del self._cache[key]
                return None

            self._cache.move_to_end(key)
            return value

    def delete(self, key: str) -> bool:
        with self._lock:
            if key not in self._cache:
                return False

            del self._cache[key]
            return True

    def cleanup_expired(self) -> int:
        with self._lock:
            now = time.monotonic()
            expired_keys = [
                key
                for key, (_, expires_at) in self._cache.items()
                if expires_at <= now
            ]

            for key in expired_keys:
                del self._cache[key]

            return len(expired_keys)

    def size(self) -> int:
        with self._lock:
            self.cleanup_expired()
            return len(self._cache)
