from collections import defaultdict
from typing import Dict, List


class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(self, dependencies: Dict[str, List[str]]) -> List[List[str]]:
        all_tasks = set(dependencies)
        for deps in dependencies.values():
            all_tasks.update(deps)

        remaining = {
            task: set(dependencies.get(task, []))
            for task in all_tasks
        }
        stages = []

        while remaining:
            ready = sorted(task for task, deps in remaining.items() if not deps)

            if not ready:
                raise CircularDependencyError("Circular dependency detected")

            stages.append(ready)
            completed = set(ready)

            for task in ready:
                del remaining[task]

            for deps in remaining.values():
                deps.difference_update(completed)

        return stages
