import asyncio
import inspect
from typing import Any, Callable, Optional


class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        if concurrency < 1:
            raise ValueError("concurrency must be at least 1")
        if max_queue_size < 1:
            raise ValueError("max_queue_size must be at least 1")

        self._concurrency = concurrency
        self._queue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._condition = asyncio.Condition()
        self._workers: list[asyncio.Task] = []
        self._sequence = 0
        self._started = False
        self._shutting_down = False
        self._shutdown_task: Optional[asyncio.Task] = None

    async def start(self) -> None:
        async with self._condition:
            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")

            if self._started:
                return

            self._started = True
            self._workers = [
                asyncio.create_task(self._worker(), name=f"async-worker-pool-{i}")
                for i in range(self._concurrency)
            ]

    async def submit(
        self,
        coro_func: Callable[..., Any],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        await self.start()

        loop = asyncio.get_running_loop()
        future = loop.create_future()

        async with self._condition:
            while self._queue.full() and not self._shutting_down:
                await self._condition.wait()

            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")

            self._sequence += 1
            self._queue.put_nowait(
                (-priority, self._sequence, coro_func, args, kwargs, future)
            )

        return future

    async def shutdown(
        self,
        drain: bool = True,
        timeout: Optional[float] = 5.0,
    ) -> None:
        async with self._condition:
            if self._shutdown_task is None:
                self._shutting_down = True
                self._condition.notify_all()
                self._shutdown_task = asyncio.create_task(
                    self._shutdown_impl(drain),
                    name="async-worker-pool-shutdown",
                )

            shutdown_task = self._shutdown_task

        if timeout is None:
            await asyncio.shield(shutdown_task)
        else:
            await asyncio.wait_for(asyncio.shield(shutdown_task), timeout=timeout)

    async def _shutdown_impl(self, drain: bool) -> None:
        try:
            if drain:
                await self._queue.join()
            else:
                await self._cancel_queued_tasks()

            for worker in self._workers:
                if not worker.done():
                    worker.cancel()

            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)

        except asyncio.CancelledError:
            await self._cancel_queued_tasks()

            for worker in self._workers:
                if not worker.done():
                    worker.cancel()

            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)

            raise

        finally:
            self._workers.clear()

    async def _cancel_queued_tasks(self) -> None:
        async with self._condition:
            while True:
                try:
                    _, _, _, _, _, future = self._queue.get_nowait()
                except asyncio.QueueEmpty:
                    break

                if not future.done():
                    future.cancel()

                self._queue.task_done()

            self._condition.notify_all()

    async def _worker(self) -> None:
        while True:
            item = await self._queue.get()
            _, _, coro_func, args, kwargs, future = item

            async with self._condition:
                self._condition.notify_all()

            try:
                if future.cancelled():
                    continue

                result = coro_func(*args, **kwargs)

                if not inspect.isawaitable(result):
                    raise TypeError("coro_func must return an awaitable")

                result = await result

                if not future.done():
                    future.set_result(result)

            except asyncio.CancelledError:
                if not future.done():
                    future.cancel()
                raise

            except Exception as exc:
                if not future.done():
                    future.set_exception(exc)

            finally:
                self._queue.task_done()
