from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        if not node_ids or len(node_ids) != len(set(node_ids)):
            raise ValueError("node_ids must be non-empty and unique")

        self.node_ids = set(node_ids)
        self.node_count = len(node_ids)
        self.quorum_threshold = self.node_count // 2 + 1

        self._partitions = [set(node_ids)]
        self._state = {node_id: {} for node_id in node_ids}
        self._versions = {node_id: {} for node_id in node_ids}
        self._clock = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        partition_a = set(group_a)
        partition_b = set(group_b)

        if (
            not partition_a
            or not partition_b
            or partition_a & partition_b
            or partition_a | partition_b != self.node_ids
        ):
            raise ValueError(
                "Partitions must be non-empty, disjoint, and include every node exactly once"
            )

        self._partitions = [partition_a, partition_b]

    def heal_partition(self) -> None:
        merged_state: dict[str, Any] = {}
        merged_versions: dict[str, int] = {}

        for node_id in self.node_ids:
            for key, value in self._state[node_id].items():
                version = self._versions[node_id][key]
                if key not in merged_versions or version > merged_versions[key]:
                    merged_state[key] = value
                    merged_versions[key] = version

        for node_id in self.node_ids:
            self._state[node_id] = merged_state.copy()
            self._versions[node_id] = merged_versions.copy()

        self._partitions = [self.node_ids.copy()]

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        if from_node not in self.node_ids:
            raise ValueError(f"Unknown node: {from_node}")

        active_partition = next(
            partition
            for partition in self._partitions
            if from_node in partition
        )

        if len(active_partition) < self.quorum_threshold:
            return False

        self._clock += 1
        for node_id in active_partition:
            self._state[node_id][key] = value
            self._versions[node_id][key] = self._clock

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self.node_ids:
            raise ValueError(f"Unknown node: {from_node}")

        return self._state[from_node].get(key)
