def parse_markdown_links(text: str) -> list[dict[str, str]]:
    """Extract valid [title](http(s)://url) links in linear time."""
    results: list[dict[str, str]] = []
    length = len(text)
    i = 0

    while i < length:
        start = text.find("[", i)
        if start == -1:
            break

        title_start = start + 1
        j = title_start

        # Scan title once; do not use backtracking regex.
        while j < length and text[j] != "]":
            if not (text[j].isalnum() or text[j] in "_ "):
                break
            j += 1

        if j == length:
            break  # Unclosed title: nothing later can close it.

        if text[j] != "]" or j == title_start:
            i = j + 1
            continue

        if j + 1 >= length or text[j + 1] != "(":
            i = j + 1
            continue

        url_start = j + 2
        if not (text.startswith("http://", url_start) or
                text.startswith("https://", url_start)):
            i = url_start
            continue

        url_end = url_start
        while url_end < length and text[url_end] not in " \t\r\n)":
            url_end += 1

        if url_end < length and text[url_end] == ")" and url_end > url_start:
            results.append({
                "title": text[title_start:j],
                "url": text[url_start:url_end],
            })
            i = url_end + 1
        else:
            i = url_end + 1

    return results
