def verify_token(username: str, token: str) -> bool:
    parts = token.strip().split("-")
    if len(parts) != 4 or any(len(p) != 4 for p in parts):
        return False
    try:
        b1, b2, b3, b4 = (int(part, 16) for part in parts)
    except ValueError:
        return False

    seed = 0x5A5A
    for ch in username:
        seed = ((seed << 5) - seed + ord(ch)) & 0xFFFF

    return (
        (b1 ^ seed) == 0xBEEF
        and (b2 ^ ((b1 * 31 + 0x1337) & 0xFFFF)) == 0xCAFE
        and (b3 ^ ((b2 * 17 + 0x7331) & 0xFFFF)) == 0xFEED
        and ((b1 + b2 + b3 + b4) & 0xFFFF) == 0x1337
    )


def generate_token(username: str) -> str:
    seed = 0x5A5A
    for ch in username:
        seed = ((seed << 5) - seed + ord(ch)) & 0xFFFF

    b1 = 0xBEEF ^ seed
    b2 = 0xCAFE ^ ((b1 * 31 + 0x1337) & 0xFFFF)
    b3 = 0xFEED ^ ((b2 * 17 + 0x7331) & 0xFFFF)
    b4 = (0x1337 - b1 - b2 - b3) & 0xFFFF

    return f"{b1:04X}-{b2:04X}-{b3:04X}-{b4:04X}"


generate_license = generate_token
