def is_safe_sql_query(query: str) -> tuple[bool, str]:
    import re
    from decimal import Decimal, InvalidOperation

    if not isinstance(query, str) or not query.strip():
        return False, "INVALID_QUERY"

    literals: dict[str, str] = {}
    output: list[str] = []
    i = 0
    literal_index = 0
    length = len(query)

    def add_literal(value: str) -> None:
        nonlocal literal_index
        marker = f"__LIT_{literal_index}__"
        literals[marker] = value
        output.append(f" {marker} ")
        literal_index += 1

    while i < length:
        char = query[i]
        next_char = query[i + 1] if i + 1 < length else ""

        # SQL comments are commonly used to evade appended predicates.
        if char == "-" and next_char == "-":
            return False, "COMMENT_EVASION"
        if char == "#":
            return False, "COMMENT_EVASION"
        if char == "/" and next_char == "*":
            return False, "COMMENT_EVASION"

        # Single-quoted SQL string literal.
        if char == "'":
            i += 1
            value: list[str] = []

            while i < length:
                if query[i] == "\\" and i + 1 < length:
                    value.append(query[i + 1])
                    i += 2
                elif query[i] == "'" and i + 1 < length and query[i + 1] == "'":
                    value.append("'")
                    i += 2
                elif query[i] == "'":
                    i += 1
                    break
                else:
                    value.append(query[i])
                    i += 1
            else:
                return False, "MALFORMED_QUERY"

            add_literal("".join(value))
            continue

        # PostgreSQL dollar-quoted string literal.
        if char == "$":
            delimiter_match = re.match(r"\$[A-Za-z_][A-Za-z0-9_]*\$|\$\$", query[i:])
            if delimiter_match:
                delimiter = delimiter_match.group(0)
                end = query.find(delimiter, i + len(delimiter))
                if end == -1:
                    return False, "MALFORMED_QUERY"
                add_literal(query[i + len(delimiter):end])
                i = end + len(delimiter)
                continue

        # Quoted identifiers: double quotes, backticks, and SQL Server brackets.
        if char in ('"', "`", "["):
            closing = "]" if char == "[" else char
            i += 1

            while i < length:
                if query[i] == closing:
                    if i + 1 < length and query[i + 1] == closing:
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    i += 1
            else:
                return False, "MALFORMED_QUERY"

            output.append(" IDENT ")
            continue

        output.append(char)
        i += 1

    normalized = re.sub(r"\s+", " ", "".join(output)).strip()

    if re.search(r"\bUNION\s+(?:ALL\s+)?SELECT\b", normalized, re.IGNORECASE):
        return False, "UNION_EXFILTRATION"

    if re.search(
        r"\b(?:pg_sleep|benchmark)\s*\(|\bwaitfor\s+delay\b",
        normalized,
        re.IGNORECASE,
    ):
        return False, "TIME_BASED_INJECTION"

    if re.search(
        r";\s*(?:DROP\b|DELETE\s+FROM\b|EXEC(?:UTE)?\b)",
        normalized,
        re.IGNORECASE,
    ):
        return False, "STACKED_QUERY"

    tokens = re.findall(
        r"__LIT_\d+__|(?:\d+(?:\.\d+)?)|[A-Za-z_][A-Za-z0-9_]*|[=()]",
        normalized,
    )

    def canonical_literal(token: str) -> tuple[str, str]:
        if token in literals:
            return "string", literals[token]
        if token.upper() in {"TRUE", "FALSE", "NULL"}:
            return "keyword", token.upper()
        try:
            return "number", str(Decimal(token))
        except InvalidOperation:
            return "other", token

    for index, token in enumerate(tokens):
        if token.upper() != "OR":
            continue

        cursor = index + 1
        while cursor < len(tokens) and tokens[cursor] == "(":
            cursor += 1

        if cursor + 2 >= len(tokens) or tokens[cursor + 1] != "=":
            continue

        left = canonical_literal(tokens[cursor])
        right = canonical_literal(tokens[cursor + 2])

        if left[0] in {"string", "number", "keyword"} and left == right:
            return False, "TAUTOLOGY_INJECTION"

    return True, "SAFE"
