import threading


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if max_connections <= 0:
            raise ValueError("max_connections must be greater than zero")
        if ping_timeout < 0:
            raise ValueError("ping_timeout must be non-negative")

        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.RLock()
        self._next_id = 1
        self._closed = False
        self._available = []
        self._connections = {}
        self._leased = set()

        for _ in range(max_connections):
            conn = self._create_connection()
            self._available.append(conn)
            self._connections[id(conn)] = conn

    def _create_connection(self) -> dict:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if self._closed or not self._available:
                raise RuntimeError("Pool exhausted")

            conn = self._available.pop()

            if not conn.get("alive", False):
                replacement = self._create_connection()
                conn.clear()
                conn.update(replacement)

            self._leased.add(id(conn))
            return conn

    def release(self, conn: dict) -> None:
        with self._lock:
            conn_key = id(conn)

            if conn_key not in self._connections:
                raise ValueError("Connection does not belong to this pool")
            if conn_key not in self._leased:
                raise ValueError("Connection is not currently acquired")

            self._leased.remove(conn_key)

            if not self._closed:
                self._available.append(conn)

    def health_check_and_heal(self) -> int:
        healed = 0

        with self._lock:
            if self._closed:
                return healed

            for conn in self._connections.values():
                if not conn.get("alive", False):
                    replacement = self._create_connection()
                    conn.clear()
                    conn.update(replacement)
                    healed += 1

        return healed

    def close_all(self) -> None:
        with self._lock:
            for conn in self._connections.values():
                conn["alive"] = False

            self._available.clear()
            self._connections.clear()
            self._leased.clear()
            self._closed = True
