import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    referenced_names = {
        node.id
        for node in ast.walk(tree)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
    }

    new_body = []

    for node in tree.body:
        if isinstance(node, ast.Import):
            kept_aliases = []

            for alias in node.names:
                bound_name = alias.asname or alias.name.split(".")[0]
                if bound_name in referenced_names:
                    kept_aliases.append(alias)

            if kept_aliases:
                node.names = kept_aliases
                new_body.append(node)

        elif isinstance(node, ast.ImportFrom):
            if any(alias.name == "*" for alias in node.names):
                new_body.append(node)
                continue

            kept_aliases = [
                alias
                for alias in node.names
                if (alias.asname or alias.name) in referenced_names
            ]

            if kept_aliases:
                node.names = kept_aliases
                new_body.append(node)

        elif (
            isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name.startswith("_")
            and node.name not in referenced_names
        ):
            continue

        else:
            new_body.append(node)

    tree.body = new_body
    ast.fix_missing_locations(tree)

    result = ast.unparse(tree)
    compile(result, "<pruned_code>", "exec")
    return result
