from collections import OrderedDict
from threading import RLock
from time import monotonic
from typing import Any, Optional


class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("capacity must be greater than zero")

        self._capacity = capacity
        self._default_ttl_seconds = default_ttl_seconds
        self._items: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self._lock = RLock()

    def set(
        self,
        key: str,
        value: Any,
        ttl: Optional[float] = None,
    ) -> None:
        with self._lock:
            expires_at = monotonic() + (
                self._default_ttl_seconds if ttl is None else ttl
            )

            if key in self._items:
                del self._items[key]
            elif len(self._items) >= self._capacity:
                now = monotonic()
                expired_items = [
                    (item_key, expiry)
                    for item_key, (_, expiry) in self._items.items()
                    if expiry <= now
                ]

                if expired_items:
                    oldest_expired_key = min(
                        expired_items,
                        key=lambda item: item[1],
                    )[0]
                    del self._items[oldest_expired_key]
                else:
                    self._items.popitem(last=False)

            self._items[key] = (value, expires_at)

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            item = self._items.get(key)
            if item is None:
                return None

            value, expires_at = item
            if expires_at <= monotonic():
                del self._items[key]
                return None

            self._items.move_to_end(key)
            return value

    def delete(self, key: str) -> bool:
        with self._lock:
            if key not in self._items:
                return False

            del self._items[key]
            return True

    def cleanup_expired(self) -> int:
        with self._lock:
            now = monotonic()
            expired_keys = [
                key
                for key, (_, expires_at) in self._items.items()
                if expires_at <= now
            ]

            for key in expired_keys:
                del self._items[key]

            return len(expired_keys)

    def size(self) -> int:
        with self._lock:
            self.cleanup_expired()
            return len(self._items)
