class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        tasks = set(dependencies)

        for deps in dependencies.values():
            tasks.update(deps)

        remaining = {
            task: set(dependencies.get(task, []))
            for task in tasks
        }

        stages = []

        while remaining:
            ready = sorted(
                task for task, deps in remaining.items()
                if not deps
            )

            if not ready:
                raise CircularDependencyError(
                    "Circular dependency detected"
                )

            stages.append(ready)

            for task in ready:
                del remaining[task]

            completed = set(ready)
            for deps in remaining.values():
                deps.difference_update(completed)

        return stages
