from collections import defaultdict, deque
import math
import threading
import time
from typing import Optional


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        if isinstance(max_requests, bool) or not isinstance(max_requests, int):
            raise TypeError("max_requests must be an integer")
        if max_requests <= 0:
            raise ValueError("max_requests must be greater than zero")
        if not isinstance(window_seconds, (int, float)) or isinstance(window_seconds, bool):
            raise TypeError("window_seconds must be a number")
        if not math.isfinite(window_seconds) or window_seconds <= 0:
            raise ValueError("window_seconds must be finite and greater than zero")

        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self._requests: dict[str, deque[float]] = defaultdict(deque)
        self._lock = threading.Lock()

    def allow_request(
        self,
        key: str,
        timestamp: Optional[float] = None,
    ) -> tuple[bool, float]:
        now = time.monotonic() if timestamp is None else float(timestamp)

        with self._lock:
            requests = self._requests[key]
            cutoff = now - self.window_seconds

            while requests and requests[0] <= cutoff:
                requests.popleft()

            if len(requests) < self.max_requests:
                requests.append(now)
                return True, 0.0

            retry_after = max(0.0, requests[0] + self.window_seconds - now)
            return False, retry_after

    def get_remaining(
        self,
        key: str,
        timestamp: Optional[float] = None,
    ) -> int:
        now = time.monotonic() if timestamp is None else float(timestamp)

        with self._lock:
            requests = self._requests.get(key)
            if not requests:
                return self.max_requests

            cutoff = now - self.window_seconds
            while requests and requests[0] <= cutoff:
                requests.popleft()

            if not requests:
                self._requests.pop(key, None)

            return max(0, self.max_requests - len(requests))
