class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        if len(node_ids) != len(set(node_ids)):
            raise ValueError("node_ids must be unique")

        self.node_ids = list(node_ids)
        self.N = len(node_ids)
        self.quorum_threshold = self.N // 2 + 1

        self._state = {node_id: {} for node_id in node_ids}
        self._partitions = [set(node_ids)]

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        group_a_set = set(group_a)
        group_b_set = set(group_b)
        cluster_nodes = set(self.node_ids)

        if len(group_a_set) != len(group_a) or len(group_b_set) != len(group_b):
            raise ValueError("Partition groups must not contain duplicates")

        if group_a_set & group_b_set:
            raise ValueError("Partition groups must be disjoint")

        if group_a_set | group_b_set != cluster_nodes:
            raise ValueError("Partition groups must contain every cluster node")

        self._partitions = [group_a_set, group_b_set]

    def heal_partition(self) -> None:
        if len(self._partitions) == 1:
            return

        authoritative_partition = max(
            self._partitions,
            key=lambda partition: len(partition)
            if len(partition) >= self.quorum_threshold
            else -1,
        )

        if len(authoritative_partition) >= self.quorum_threshold:
            source_node = next(iter(authoritative_partition))
            committed_state = dict(self._state[source_node])

            for node_id in self.node_ids:
                self._state[node_id] = dict(committed_state)

        self._partitions = [set(self.node_ids)]

    def propose_write(self, from_node: str, key: str, value: any) -> bool:
        if from_node not in self._state:
            raise ValueError(f"Unknown node: {from_node}")

        active_partition = next(
            partition
            for partition in self._partitions
            if from_node in partition
        )

        if len(active_partition) < self.quorum_threshold:
            return False

        for node_id in active_partition:
            self._state[node_id][key] = value

        return True

    def read_value(self, from_node: str, key: str) -> any:
        if from_node not in self._state:
            raise ValueError(f"Unknown node: {from_node}")

        return self._state[from_node].get(key)
