def verify_jwt(
    token: str,
    secret_key: str,
    allowed_algs: list[str] | None = None,
) -> dict:
    if allowed_algs is None:
        allowed_algs = ["HS256"]

    def decode_b64url(value: str) -> bytes:
        if not isinstance(value, str) or len(value) % 4 == 1:
            raise ValueError("Invalid Base64 encoding")

        padded = value + ("=" * (-len(value) % 4))
        try:
            return base64.b64decode(
                padded,
                altchars=b"-_",
                validate=True,
            )
        except (ValueError, TypeError):
            raise ValueError("Invalid Base64 encoding")

    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    try:
        header = json.loads(decode_b64url(parts[0]))
        payload = json.loads(decode_b64url(parts[1]))
    except (ValueError, json.JSONDecodeError):
        raise ValueError("Invalid JWT format")

    if not isinstance(header, dict) or not isinstance(payload, dict):
        raise ValueError("Invalid JWT format")

    alg = header.get("alg")
    if not isinstance(alg, str) or alg == "none" or alg not in allowed_algs:
        raise ValueError("Unapproved algorithm")

    hash_algorithms = {
        "HS256": hashlib.sha256,
        "HS384": hashlib.sha384,
        "HS512": hashlib.sha512,
    }

    digestmod = hash_algorithms.get(alg)
    if digestmod is None:
        raise ValueError("Unsupported algorithm")

    signature = decode_b64url(parts[2])
    signing_input = f"{parts[0]}.{parts[1]}".encode("utf-8")
    expected_sig = hmac.new(
        secret_key.encode("utf-8"),
        signing_input,
        digestmod,
    ).digest()

    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")

    if "exp" in payload:
        try:
            if payload["exp"] <= time.time():
                raise ValueError("Token expired")
        except TypeError:
            raise ValueError("Invalid expiration")

    return payload
