def parse_markdown_links(text: str) -> list[dict[str, str]]:
    """Extract markdown links in deterministic linear time."""
    results: list[dict[str, str]] = []
    n = len(text)
    i = 0

    while i < n:
        start = text.find("[", i)
        if start == -1:
            break

        j = start + 1
        while j < n:
            ch = text[j]
            if (
                "A" <= ch <= "Z"
                or "a" <= ch <= "z"
                or "0" <= ch <= "9"
                or ch == "_"
                or ch.isspace()
            ):
                j += 1
            else:
                break

        if j == start + 1 or j + 1 >= n or text[j:j + 2] != "](":
            i = max(j, start + 1)
            continue

        url_start = j + 2
        if text.startswith("https://", url_start):
            scheme_end = url_start + 8
        elif text.startswith("http://", url_start):
            scheme_end = url_start + 7
        else:
            next_start = text.find("[", url_start)
            i = n if next_start == -1 else next_start
            continue

        k = scheme_end
        while k < n and not text[k].isspace() and text[k] != ")":
            k += 1

        if k < n and text[k] == ")" and k > scheme_end:
            results.append({
                "title": text[start + 1:j],
                "url": text[url_start:k],
            })
            i = k + 1
        else:
            i = k if k < n else n

    return results
```

This uses deterministic scanning with a forward-only cursor, so it avoids regex backtracking and runs in linear time.

