def is_safe_sql_query(query: str) -> tuple[bool, str]:
    import re

    if not isinstance(query, str):
        return False, "INVALID_INPUT"

    sql = re.sub(r"\s+", " ", query).strip()
    if not sql:
        return True, "SAFE"

    tokens = []
    comments = []
    marked = []
    raw_clean = []
    malformed = False
    sentinel = "\x00"
    i = 0
    length = len(sql)

    while i < length:
        char = sql[i]

        if char in "'\"`":
            quote = char
            start = i
            value = []
            i += 1
            closed = False

            while i < length:
                if sql[i] == quote:
                    if i + 1 < length and sql[i + 1] == quote:
                        value.append(quote)
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                elif sql[i] == "\\" and quote != "`" and i + 1 < length:
                    value.append(sql[i + 1])
                    i += 2
                else:
                    value.append(sql[i])
                    i += 1

            marked.append(sql[start:i])
            raw_clean.append(sql[start:i])
            tokens.append(("STRING", "".join(value)))

            if not closed:
                malformed = True
            continue

        dollar_match = re.match(r"\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$", sql[i:])
        if dollar_match:
            delimiter = dollar_match.group(0)
            end = sql.find(delimiter, i + len(delimiter))

            if end == -1:
                marked.append(sql[i:])
                raw_clean.append(sql[i:])
                tokens.append(("STRING", sql[i + len(delimiter):]))
                malformed = True
                break

            end += len(delimiter)
            marked.append(sql[i:end])
            raw_clean.append(sql[i:end])
            tokens.append(("STRING", sql[i + len(delimiter):end - len(delimiter)]))
            i = end
            continue

        if sql.startswith("--", i):
            end = sql.find("\n", i + 2)
            if end == -1:
                end = length
            comments.append(sql[i:end])
            marked.append(" ")
            raw_clean.append(" ")
            i = end
            continue

        if sql.startswith("#", i):
            end = sql.find("\n", i + 1)
            if end == -1:
                end = length
            comments.append(sql[i:end])
            marked.append(" ")
            raw_clean.append(" ")
            i = end
            continue

        if sql.startswith("/*", i):
            end = sql.find("*/", i + 2)
            if end == -1:
                comments.append(sql[i:])
                marked.append(sentinel)
                raw_clean.append(" ")
                malformed = True
                break

            end += 2
            comments.append(sql[i:end])
            marked.append(sentinel)
            raw_clean.append(" ")
            i = end
            continue

        identifier = re.match(r"[A-Za-z_][A-Za-z0-9_$]*", sql[i:])
        if identifier:
            value = identifier.group(0).upper()
            tokens.append(("IDENT", value))
            marked.append(identifier.group(0))
            raw_clean.append(identifier.group(0))
            i += len(identifier.group(0))
            continue

        number = re.match(r"(?:\d+(?:\.\d*)?|\.\d+)", sql[i:])
        if number:
            value = number.group(0)
            tokens.append(("NUMBER", value))
            marked.append(value)
            raw_clean.append(value)
            i += len(value)
            continue

        if sql.startswith("==", i):
            tokens.append(("SYMBOL", "=="))
            marked.append("==")
            raw_clean.append("==")
            i += 2
            continue

        tokens.append(("SYMBOL", char))
        marked.append(char)
        raw_clean.append(char)
        i += 1

    marked_sql = "".join(marked)
    clean_sql = "".join(raw_clean)

    if any(re.match(r"/\*!\s*\d*", comment, re.IGNORECASE) for comment in comments):
        return False, "OBFUSCATED_COMMENT"

    sensitive_keywords = (
        "UNION",
        "SELECT",
        "EXEC",
        "EXECUTE",
        "DROP",
        "DELETE",
        "UPDATE",
        "INSERT",
        "WAITFOR",
        "SLEEP",
        "PG_SLEEP",
        "BENCHMARK",
        "XP_CMDSHELL",
    )

    for keyword in sensitive_keywords:
        pattern = re.escape(keyword[0])
        for character in keyword[1:]:
            pattern += rf"(?:\s*{re.escape(sentinel)}\s*)?{re.escape(character)}"
        if re.search(rf"\b{pattern}\b", marked_sql, re.IGNORECASE):
            return False, "OBFUSCATED_COMMENT"

    statement_starters = {
        "SELECT", "WITH", "INSERT", "UPDATE", "DELETE", "DROP",
        "ALTER", "TRUNCATE", "CREATE", "EXEC", "EXECUTE",
        "GRANT", "REVOKE", "MERGE",
    }

    for index, (_, value) in enumerate(tokens):
        if value == ";" and index + 1 < len(tokens):
            if tokens[index + 1][1] in statement_starters:
                return False, "STACKED_QUERY"

    for index, (_, value) in enumerate(tokens):
        if value == "UNION":
            next_index = index + 1
            if next_index < len(tokens) and tokens[next_index][1] == "ALL":
                next_index += 1
            if next_index < len(tokens) and tokens[next_index][1] == "SELECT":
                return False, "UNION_EXFILTRATION"

    time_functions = {"SLEEP", "PG_SLEEP", "BENCHMARK"}

    for index, (_, value) in enumerate(tokens):
        if value in time_functions:
            if index + 1 < len(tokens) and tokens[index + 1][1] == "(":
                return False, "TIME_BASED_BLIND"
        if value == "WAITFOR":
            if index + 1 < len(tokens) and tokens[index + 1][1] == "DELAY":
                return False, "TIME_BASED_BLIND"
        if value in {"EXEC", "EXECUTE"}:
            if index + 1 < len(tokens) and tokens[index + 1][1] == "XP_CMDSHELL":
                return False, "STACKED_QUERY"

    tautology_pattern = re.compile(
        r"""(['"])\s*(?:OR|AND)\s*\1\s*
            ([A-Za-z0-9_]+)\s*\1\s*=\s*\1\s*\2\s*\1""",
        re.IGNORECASE | re.VERBOSE,
    )

    numeric_tautology_pattern = re.compile(
        r"""(['"])\s*(?:OR|AND)\s*
            ([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*=\s*\2""",
        re.IGNORECASE | re.VERBOSE,
    )

    if tautology_pattern.search(clean_sql) or numeric_tautology_pattern.search(clean_sql):
        return False, "BOOLEAN_TAUTOLOGY"

    if re.search(r"\b[A-Za-z_][A-Za-z0-9_$]*\s*['\"]\s*--", sql, re.IGNORECASE):
        return False, "BOOLEAN_TAUTOLOGY"

    def is_constant(token):
        kind, value = token
        return kind in {"NUMBER", "STRING"} or (
            kind == "IDENT" and value in {"TRUE", "FALSE", "NULL"}
        )

    for index, (_, value) in enumerate(tokens):
        if value not in {"OR", "AND"}:
            continue

        if index + 1 < len(tokens) and tokens[index + 1][1] in {"TRUE", "FALSE"}:
            return False, "BOOLEAN_TAUTOLOGY"

        if index + 3 >= len(tokens):
            continue

        left = tokens[index + 1]
        operator = tokens[index + 2][1]
        right = tokens[index + 3]

        if operator in {"=", "=="} and is_constant(left) and is_constant(right):
            if left[1].upper() == right[1].upper():
                return False, "BOOLEAN_TAUTOLOGY"

    if malformed:
        return False, "MALFORMED_SQL"

    return True, "SAFE"
