import threading


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if not isinstance(max_connections, int) or max_connections <= 0:
            raise ValueError("max_connections must be a positive integer")
        if ping_timeout < 0:
            raise ValueError("ping_timeout must be non-negative")

        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.RLock()
        self._next_id = 1
        self._available = []
        self._in_use = {}

        for _ in range(max_connections):
            self._available.append(self._new_connection())

    def _new_connection(self) -> dict:
        connection = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return connection

    def acquire(self) -> dict:
        with self._lock:
            if not self._available:
                raise RuntimeError("Pool exhausted")

            connection = self._available.pop()
            self._in_use[id(connection)] = connection
            return connection

    def release(self, conn: dict) -> None:
        with self._lock:
            key = id(conn)
            if self._in_use.get(key) is not conn:
                raise ValueError("Connection does not belong to this pool")

            del self._in_use[key]
            self._available.append(conn)

    def health_check_and_heal(self) -> int:
        healed = 0

        with self._lock:
            connections = list(self._available) + list(self._in_use.values())

            for connection in connections:
                if connection.get("alive") is False:
                    replacement = self._new_connection()
                    connection.clear()
                    connection.update(replacement)
                    healed += 1

        return healed

    def close_all(self) -> None:
        with self._lock:
            self._available.clear()
            self._in_use.clear()
