def prune_dead_code_and_imports(source_code: str) -> str:
    import ast

    tree = ast.parse(source_code)

    private_functions = {
        node.name
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name.startswith("_")
    }

    referenced_names = {
        node.id
        for node in ast.walk(tree)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
    }

    dead_private_functions = private_functions - referenced_names

    class Pruner(ast.NodeTransformer):
        def visit_Module(self, node):
            node.body = [
                statement
                for statement in node.body
                if not (
                    isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef))
                    and statement.name in dead_private_functions
                )
            ]
            return self.generic_visit(node)

        def visit_Import(self, node):
            kept = []

            for alias in node.names:
                bound_name = alias.asname or alias.name.split(".", 1)[0]
                if bound_name in referenced_names:
                    kept.append(alias)

            return node if kept and (node.names := kept) else None

        def visit_ImportFrom(self, node):
            if node.module == "__future__":
                return node

            if any(alias.name == "*" for alias in node.names):
                return node

            kept = [
                alias
                for alias in node.names
                if (alias.asname or alias.name) in referenced_names
            ]

            if not kept:
                return None

            node.names = kept
            return node

    pruned_tree = Pruner().visit(tree)
    ast.fix_missing_locations(pruned_tree)

    result = ast.unparse(pruned_tree)
    compile(result, "<pruned>", "exec")
    return result
